(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["multimodal"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-duet-vlm-two-stage"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-1\">一 · 事故现场：一次跨任务上线后的精度回退</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-2\">二 · 它到底解决哪个推理问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-3\">三 · 推理系统代价落在哪里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-4\">四 · 它明确不解决的问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-5\">五 · 适用边界的工程判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-6\">六 · 从 ViT 输出到粗筛集合：第一阶段的输入、输出与代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-7\">七 · 拼接与浅层前向：被压缩序列进入 LLM 的入口代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-8\">八 · 第二阶段细筛：TopK 的输入、输出与一次前向的账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-9\">九 · 后续层与 KV 维护：压缩如何传导到解码吞吐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-10\">十 · 两阈值的一致性约束与跨任务重校准</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-11\">十一 · 两阶段筛选的边界条件与系统代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-12\">十二 · 第一阶段集合式筛选的逐项拆解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-13\">十三 · 第二阶段 TopK 与注意力分数的口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-14\">十四 · 两阶段判据不一致的失效路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-15\">十五 · 伪代码落到可实现</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-16\">十六 · 与单阶段压缩的公式级差别</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-17\">十七 · 边界条件：阈值失配、短请求与两阶段判据打架</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-18\">十八 · 请求形态：什么样的输入让两阶段真正省</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-19\">十九 · 长度分布：压缩率与开销的交叉点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-20\">二十 · 并发与批大小：打分开销在批维上的摊薄</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-21\">二十一 · 负载不对时的三种失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-22\">二十二 · 配方落地：路由、分桶与阈值绑定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-23\">二十三 · 短请求与长视觉序列下的收益反转</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-24\">二十四 · 硬件档位：按“两段前向”拆资源，而不是按整卡规格挑</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-25\">二十五 · 并行拓扑：TP 跟着打分前向走，PP 跟着保留 token 的 KV 走</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-26\">二十六 · 量化方案：分段量化，视觉段与打分前向不共享一套精度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-27\">二十七 · KV 策略：按 $N_{\\text{eff}}$ 分配、按阶段释放、按请求回收</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-28\">二十八 · 调度参数：批形状按 $N_{\\text{eff}}$ 分组，打分前向单独成批</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-29\">二十九 · 可复现配置思路：先定阈值、再定拓扑、最后定量化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-30\">三十 · 两阶段筛选的显存账：KV 只对幸存者记账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-31\">三十一 · 带宽与算力的错配：省下的是 HBM 流量，不是 MMA</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-32\">三十二 · 通信面：压缩发生在集合通信之前才有价值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-33\">三十三 · 功耗与热：压缩改变的是功耗曲线的形状</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-34\">三十四 · 尾延迟：阈值不确定性与两阶段不一致</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-35\">三十五 · 规模上限的排序：先崩的是调度，不是硬件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-36\">三十六 · 双阶段管线的系统代价：从短请求到规模上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-37\">三十七 · 阈值漂移：跨任务精度回退的定位方法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-38\">三十八 · OOM 的三个来源与显存核算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-39\">三十九 · 批抖动与路由不均：两个不同的问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-40\">四十 · 尾延迟尖刺：打分开销与短请求的错配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-41\">四十一 · 两阶段标准不一致导致的误删</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-42\">四十二 · 监控指标与回滚策略</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-43\">四十三 · 双阈值失配与浅层打分的失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-44\">四十四 · 对照维度：压缩发生在哪一段数据流上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-45\">四十五 · 判据异质性的代价：阈值耦合与校准负担</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-46\">四十六 · 与“不减 token”家族的边界：压缩与量化的正交性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-47\">四十七 · 与逐层压缩的时序差异：一次性判决 vs 渐进收缩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-48\">四十八 · 决策表：按瓶颈、序列形态与任务漂移选型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-49\">四十九 · 组合与迁移：把 DUET-VLM 当管线的一段而非全部</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-duet-vlm-two-stage-sec-50\">五十 · 同族选型：双阶段何时优于单阶段与纯相关性筛选</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:482px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 482.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">ViT 输出全部视觉 token</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">第一阶段按 patch 间相似度剔除高冗余 token</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">拼接文本后进入 LLM 前若干层</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">第二阶段用浅层跨模态注意力分数选出关键 token</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">后续层仅对保留 token 计算并维护 KV</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-duet-vlm-two-stage-sec-1\">一 · 事故现场：一次跨任务上线后的精度回退</h3>\n<p>某条 VLM 在线服务在图像问答任务上完成调优，第一阶段相似度阈值 τ₁ 与第二阶段注意力阈值 τ₂ 都按该任务的样本分布校准过，预填阶段的视觉 token 数量被压到较低水平，端到端延迟与吞吐都达到预期。随后同一套服务被复用到文档图表理解与细粒度 OCR 类请求上，配置未变。上线后出现一类难以定位的故障：模型对图中数字、小字号标签、表格边线的回答开始出现系统性错误，而纯文本请求与粗粒度物体识别请求几乎不受影响。日志里没有异常，显存与带宽指标正常，延迟甚至更好——因为被剔除的 token 更多了。</p>\n<p>根因不在模型权重，而在压缩管线的阈值语义发生了漂移。第一阶段按 patch 间相似度剔除高冗余 token，判据是空间邻域内的表示相似度：纹理平坦区域、纯色背景、重复的表格线，其 patch 表示彼此高度相似，会被判为冗余。在自然图像问答里这是合理的，因为被剔除的多是背景；但在文档图表里，一条细边线、一个小数点、一个上标数字恰恰是低冗余、高信息密度的 token，它们与邻域的相似度并不高，本应保留。问题出在 τ₁ 被调得偏松之后，连同一些中等相似度的细节 token 一起被划入剔除集合，而第二阶段的跨模态注意力打分只能从第一阶段留下的集合 $\\mathcal{S}_1$ 里做 TopK，无法把已经丢掉的 token 找回来。这就是失败模式里“关键 token 在两阶段间被误删，KV 上下文不足”的具体形态：后续层只对保留 token 计算并维护 KV，被误删的视觉证据在浅层之后彻底缺席，解码阶段的注意力没有任何可回退的路径。</p>\n<p>这个事故说明的不是“压缩有害”，而是单一阈值集合无法覆盖异构任务分布。它同时暴露了另一个更隐蔽的问题：如果训练阶段使用的压缩策略与推理阶段不同——例如训练时保留全部视觉 token、推理时才启用两阶段剔除——模型在训练中从未见过被压缩后的上下文分布，浅层注意力分数的统计特性与推理时不匹配，精度回退会以更难解释的方式出现。DUET-VLM 把训练与推理统一到同一条双阶段管线上，正是针对这一点。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-2\">二 · 它到底解决哪个推理问题</h3>\n<p>把问题拆成两个互相纠缠的子问题。其一是压缩位置的选择困境：在视觉编码器侧做压缩，优点是省掉后续所有层的计算与 KV，缺点是编码器尚未与文本交互，缺少任务相关性信号，只能依据图像自身的冗余度判断，容易丢失对当前提问关键的细节；在 LLM 侧做压缩，优点是浅层跨模态注意力已经携带了“这个问题在看哪里”的信息，缺点是此时视觉 token 已经走过了若干层，KV 已经写入，压缩只能减少后续层的计算，无法回收已付出的预填代价。其二是训练-推理一致性：很多压缩方法在推理管线里插入剪枝逻辑，但训练时并不启用，导致模型实际面对的上下文长度分布与训练分布不一致。</p>\n<p>DUET-VLM 的答案是两阶段串联，让两个位置各自发挥长处。第一阶段在 ViT 输出之后按 patch 间相似度做粗粒度冗余剔除，此时没有任何文本信息，判据只能是图像内部的空间冗余，因此它只负责剔除“高置信的冗余”，阈值应当保守；第二阶段在 LLM 前若干层用浅层跨模态注意力分数做细粒度筛选，此时文本已经参与，显著性带有任务相关性，可以承担更大的压缩比例。两阶段互补的实质是：第一阶段用低成本、无文本的判据砍掉大头，第二阶段用高成本、有文本的判据精修。压缩率高于单阶段方法，因为没有任何单一判据能同时具备“便宜”与“任务相关”两种属性。</p>\n<p>形式化地，两阶段筛选写作</p>\n<div class=\"formula\">$$\\mathcal{S}_1 = \\{j \\mid \\max_{i\\in\\mathcal{N}(j)} \\mathrm{sim}(\\mathbf{v}_j,\\mathbf{v}_i) &lt; \\tau_1\\},\\quad \\mathcal{S}_2 = \\mathrm{TopK}(\\{a_j\\}, k),\\ j\\in\\mathcal{S}_1$$</div>\n<p>其中 $\\mathbf{v}_j$ 为 patch 表示、$\\mathcal{N}(j)$ 为空间邻域、$\\tau_1$ 为相似度阈值、$a_j$ 为浅层跨模态注意力分数。等价的逐 token 判据可写成</p>\n<div class=\"formula\">$$\\text{keep}_i=\\mathbb{1}\\left[\\text{sim}(v_i,\\mathcal{N}(v_i))&lt;\\tau_1\\right]\\cdot\\mathbb{1}\\left[a_i^{(l)}&gt;\\tau_2\\right],\\quad N_{\\text{eff}}=\\sum_i \\text{keep}_i$$</div>\n<p>两个指示函数的乘积结构说明了一件事：任一阶段判否，token 即被丢弃，不存在第二阶段“捞回”的可能。这正是事故的技术根源，也是调参时必须把 τ₁ 设得比 τ₂ 更保守的原因——第一阶段的错误不可逆，第二阶段的错误至少还发生在有文本信号的条件下。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-3\">三 · 推理系统代价落在哪里</h3>\n<p>收益侧很清楚：后续层仅对保留 token 计算并维护 KV，$N_{\\text{eff}}$ 直接决定预填阶段注意力的计算量与 KV cache 的写入量。在长视觉序列、大批量并发预填的场景下，KV 显存占用与注意力带宽随 $N_{\\text{eff}}$ 线性下降，这是吞吐的主要来源。代价侧则集中在三处，且都不是免费的。</p>\n<ul>\n<li>额外的一次前向与调度开销。第二阶段需要在 LLM 浅层插入打分逻辑，意味着在正式的大规模前向之前，先要让视觉 token 与文本 token 一起走过若干层以取得跨模态注意力分数 $a_j$，再据此裁剪，然后继续后续层。这段“探测性前向”的计算量按浅层数计，调度上还要在裁剪点插入一次同步与重排，批内不同请求的 $N_{\\text{eff}}$ 不同，会造成批内负载不均。</li>\n<li>阈值调参成本。τ₁ 与 τ₂ 需按任务调参，跨任务泛化需重新校准。这不是一次性配置，而是随请求分布漂移持续存在的运维负担；事故里精度回退难以定位，正是因为阈值语义与任务语义的对应关系不写在任何监控指标里。</li>\n<li>短请求上的收益倒挂。浅层打分开销在短序列请求上占比更高。当视觉 token 本就不多、文本很短时，探测性前向与裁剪调度的固定成本可能超过压缩省下的计算，压缩收益被开销抵消。这是适用边界里必须明确的一条：该算法面向需要兼顾精度与吞吐的 VLM 推理，但在短序列、小 batch 的请求形态下，两阶段管线的净收益需要重新核算。</li>\n</ul>\n<p>用一个具体例子把代价量化到机制层面：设某请求 ViT 输出 $N$ 个视觉 token，第一阶段剔除后剩 $\\alpha N$，第二阶段 TopK 后剩 $k$。后续层的注意力计算与 KV 写入按 $k$ 计，相比不压缩的 $N$ 节省比例约为 $1-k/N$；但探测性前向要对 $\\alpha N$ 个视觉 token 加文本 token 跑 $l$ 层，这部分成本与 $\\alpha N \\cdot l$ 成正比，且不随 $k$ 缩小。当 $k/N$ 很小而 $l$ 相对总层数不可忽略时，净收益取决于 $N$ 是否足够大以摊薄固定开销——这解释了为什么该算法在长视觉序列上收益显著，而在短请求上需要谨慎。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-4\">四 · 它明确不解决的问题</h3>\n<p>边界要写清楚，否则会被误用。第一，它不解决跨任务泛化本身。两个阈值需按任务调参，跨任务部署需重新校准，算法没有提供自动校准机制，也没有给出规模上限。把一套阈值直接搬到新任务上，就是事故里那条失败路径。第二，它不解决视觉缓存复用层面的问题——跨请求、跨轮次的视觉特征复用属于另一条机制线，DUET-VLM 的压缩发生在单次请求的管线内部，不涉及缓存命中与失效策略。第三，它不解决量化层面的精度问题，NVFP4/FP8 下的数值行为与 token 缩减是正交的两件事，压缩率提高会改变激活分布，但不替代量化校准。第四，它不解决并行与通信拓扑的选型，硬件档位、并行拓扑与量化配置在给定事实中均未给出，说明该算法的收益评估必须放在具体部署配方下重做，而不能当作与硬件无关的常数。</p>\n<p>还有一条容易混淆的边界：它与 ViTCoP 的差别在于压缩分两阶段——编码器后按 patch 相似度粗筛，LLM 浅层再用跨模态注意力显著性细筛；ViTCoP 只在预填前做一次文本相关性筛选与合并。这意味着 DUET-VLM 的管线更长、插入点更多，调度复杂度更高；在只需要一次文本相关性筛选就能达到目标压缩率的场景下，两阶段的额外开销未必值得。判断标准是：任务分布是否异构到单一判据无法覆盖，以及视觉序列是否长到足以摊薄探测性前向的成本。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-5\">五 · 适用边界的工程判据</h3>\n<p>把适用性写成可操作的判断，而不是定性描述。第一条判据是任务异构度：如果线上请求混合了自然图像问答与文档细粒度理解，单一阈值集合必然在某一边出现回退，此时两阶段的价值在于把“无文本判据”与“有文本判据”分开调参，让第一阶段的保守性与第二阶段的激进性各自独立。第二条判据是视觉序列长度与批大小：$N$ 越大、批越满，探测性前向的固定开销被摊薄得越充分，$1-k/N$ 的节省才真正转化为吞吐；短序列小批场景应优先考虑单阶段方案或直接不压缩。第三条判据是训练-推理一致性：如果训练管线无法与推理共享同一双阶段管线，压缩带来的分布偏移会以精度回退的形式出现，此时应把该算法视为需要重训配合的方案，而非纯推理侧插件。</p>\n<p>事故复盘给出的最终工程判断落在阈值语义上：第一阶段判据是图像内部相似度，与任务无关，因此 τ₁ 的校准目标是“不漏删细节”，宁可少删；第二阶段判据是跨模态注意力显著性，与任务强相关，τ₂ 或 TopK 的 $k$ 才是承担压缩率的主要旋钮。把压缩率的主要责任放在第二阶段，同时把第一阶段的剔除限制在高置信冗余上，可以让跨任务部署时的回退幅度可控——因为任务相关性信号只影响第二阶段，而第二阶段的错误发生在文本已经参与之后，至少具备可观测的注意力依据。反过来，若把 τ₁ 调松以追求更高压缩率，就等于让一个与任务无关的判据决定关键 token 的生死，事故里的精度回退正是这条路径的必然结果。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-6\">六 · 从 ViT 输出到粗筛集合：第一阶段的输入、输出与代价</h3>\n<p>DUET-VLM 的第一步发生在视觉编码器之后、文本拼接之前。输入是 ViT 产出的全部 patch 级视觉 token 及其空间邻域结构；输出是一个被粗筛后的子集 $\\mathcal{S}_1$。判定逻辑是：对每个 patch 表示 $\\mathbf{v}_j$，取其在空间邻域 $\\mathcal{N}(j)$ 内最相似的那个邻居，若最大相似度仍低于阈值 $\\tau_1$，说明该 patch 与周围冗余度低、携带独立信息，予以保留；反之则视为可被邻居代表而剔除。写成集合形式即</p>\n<div class=\"formula\">$$\\mathcal{S}_1 = \\{j \\mid \\max_{i\\in\\mathcal{N}(j)} \\mathrm{sim}(\\mathbf{v}_j,\\mathbf{v}_i) &lt; \\tau_1\\}$$</div>\n<p>这一步的代价结构很干净：相似度计算是纯视觉侧的点积或余弦，规模为 $O(|\\mathcal{V}|\\cdot|\\mathcal{N}|)$，与 LLM 无关，因此不占 LLM 的 KV 显存，也不引入跨模态依赖。真正的系统代价在带宽与调度上——ViT 输出全部 token 后要先落到显存或片上缓冲，再做邻域比较，这一趟读写是第一阶段的主要开销；剔除动作本身只是索引级的 gather，不涉及矩阵乘。举例来说，一张被切成大量 patch 的高分辨率图，若大片区域是纯色背景或重复纹理，第一阶段会把它们压成极少数代表 token，后续拼接进文本序列的视觉长度随之下降，LLM 预填的注意力矩阵规模按平方级缩小。这里的关键工程判断是：$\\tau_1$ 定得松，粗筛几乎不做事，第二阶段独自承担压缩压力；$\\tau_1$ 定得紧，细节 token 在进入 LLM 之前就被删掉，而 LLM 侧再无机会把它们找回来——这正是失败模式里“第一阶段剔除过多细节 token、精度回退且难以定位”的来源。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-7\">七 · 拼接与浅层前向：被压缩序列进入 LLM 的入口代价</h3>\n<p>粗筛后的视觉 token 与文本 token 拼接，形成多模态输入序列，送入 LLM 的前若干层。这一步的输入是 $\\mathcal{S}_1$ 对应的视觉表示加文本嵌入，输出是这些层产生的隐状态与浅层跨模态注意力分数 $a_j$。注意，此时序列长度已经比“全视觉 token + 文本”短，因此前若干层的预填 FLOPs 和激活显存都按比例下降；但下降不是免费的——拼接点要做一次视觉到文本隐藏维度的投影（若框架未做早期融合），这是一次小矩阵乘，代价与保留 token 数成正比。</p>\n<p>更值得关注的是调度侧：第二阶段要求在 LLM 浅层插入打分逻辑，这意味着前若干层不能按纯标准前向一口气跑完，而要在特定层停下来取注意力分数、做 TopK、再裁剪序列继续后续层。这个“停下来”的动作在连续批处理（continuous batching）里会打断 kernel 融合的连续性，形成一次额外的调度同步点。对长序列请求，这次同步被摊薄；对短请求，它的占比上升，正是“短请求上压缩收益被开销抵消”的机制根源。工程上可做的缓解是把打分逻辑融进该层注意力的 epilogue，让分数在注意力 kernel 写出时顺带落盘，避免单独一次前向。这一步的显存代价是双份的：既要保留浅层 KV 供打分读取，又要在裁剪后重建后续层的 KV 布局。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-8\">八 · 第二阶段细筛：TopK 的输入、输出与一次前向的账</h3>\n<p>第二阶段的输入是第一阶段留下的 $\\mathcal{S}_1$ 及其在浅层产生的跨模态注意力分数 $\\{a_j\\}$，输出是最终保留集 $\\mathcal{S}_2$：</p>\n<div class=\"formula\">$$\\mathcal{S}_2 = \\mathrm{TopK}(\\{a_j\\}, k),\\ j\\in\\mathcal{S}_1$$</div>\n<p>这里的 $a_j$ 是视觉 token 对文本 query 的注意力显著性——它回答的是“这个 patch 对当前这条文本请求有没有用”，与第一阶段的“这个 patch 和邻居是否重复”是两个正交标准。两阶段串联的价值就在此：第一阶段删的是信息冗余，第二阶段删的是任务无关。代价上，TopK 本身是 $O(|\\mathcal{S}_1|\\log k)$ 的排序或选择，相对注意力计算可忽略；真正的代价是它依赖的那一次浅层前向——必须先把 $\\mathcal{S}_1$ 送进 LLM 若干层才能拿到分数，这段前向的 FLOPs 无法被第二阶段省掉，只能被第一阶段的粗筛部分削减。</p>\n<p>系统账要这么算：设全视觉长度为 $N_v$，粗筛保留率为 $r_1$，细筛保留 $k$ 个。浅层前向的注意力代价按 $(r_1 N_v + N_t)^2$ 计，后续层的代价按 $(k + N_t)^2$ 计，其中 $N_t$ 为文本长度。当 $N_t$ 很小而 $N_v$ 很大时，两阶段收益最显著；当 $N_t$ 与 $N_v$ 同量级，粗筛带来的平方项缩减被文本项稀释，浅层打分的那一次前向就更难摊薄。这也是为什么该机制在图像重、文本轻的请求上收益最确定。KV 侧，后续层只为 $\\mathcal{S}_2$ 维护 KV，KV cache 的视觉部分容量从 $N_v$ 降到 $k$，直接决定了解码阶段每步可容纳的并发请求数。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-9\">九 · 后续层与 KV 维护：压缩如何传导到解码吞吐</h3>\n<p>细筛之后，后续层只对 $\\mathcal{S}_2$ 计算并维护 KV。输入是裁剪后的序列，输出是标准的下一个 token 分布，以及一份尺寸缩小的 KV cache。这一步没有新的算法逻辑，但它是全部压缩收益的兑现点：预填阶段省的是注意力矩阵的平方项，解码阶段省的是每步都要读一遍的 KV 带宽。解码是访存密集的，每生成一个 token 要把历史 KV 从 HBM 读进 SM，视觉 KV 从 $N_v$ 降到 $k$ 意味着每步的字节数按比例下降，在固定带宽下直接换成更低的单 token 延迟或更大的批。</p>\n<p>工程上要小心 KV 布局的连续性：裁剪发生在层间，若框架已按最大序列长度预分配了 paged KV 块，裁剪只是逻辑索引的收缩，物理块可复用；但若实现按层重建紧凑布局，就会引入一次显存搬运，把省下的带宽又吐回去一部分。一个具体例子：NVL72 级别的部署里，单卡 HBM 容量决定了单副本能挂多少并发序列，视觉 KV 压缩后同一张卡能多容纳若干条图像请求，解码批变大，SM 的访存流水更容易打满——这是压缩从“省显存”转化为“提吞吐”的路径。反过来，若第二阶段保留的 $k$ 设得过大，KV 缩减不明显，浅层打分开销却照付，净收益为负。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-10\">十 · 两阈值的一致性约束与跨任务重校准</h3>\n<p>把四个步骤串起来看，真正的脆弱点在两个阈值 $\\tau_1$、$\\tau_2$（或等价的 $k$）之间的标准一致性。第一阶段按几何相似度删，第二阶段按任务显著性删，两套标准若不一致，就会出现“第一阶段留下的 token 在第二阶段被判定为无关而删掉，但它其实是唯一携带某细节的 token”——关键 token 在两阶段间被误删，后续层 KV 上下文不足，模型只能凭残缺上下文作答。这类错误不会在单阶段方法里出现，因为单阶段只有一个判据。工程上的防御是让第二阶段在 $\\mathcal{S}_1$ 上做 TopK 时保留一个下限配额，或在打分逻辑里显式惩罚“其邻域已被第一阶段大量剔除”的 token，避免冗余判据与显著性判据互相拆台。</p>\n<p>跨任务部署时，$\\tau_1$ 必须重新校准：文档 OCR 类请求的 patch 相似度分布与自然图像、图表截图的分布不同，用同一 $\\tau_1$ 会把文字笔画当成冗余纹理剔掉。校准成本落在部署侧——每换一个任务域就要重跑一遍阈值扫描，这是该机制相对单阶段方法多出来的运维代价。训练与推理共享同一双阶段管线则消除了另一类代价：训练时若用一套压缩、推理时换另一套，精度回退无法归因；共享管线让压缩率在两侧一致，精度曲线可预测。最后一段落在具体机制上：短请求场景下，浅层打分那次前向的固定开销无法被压缩收益覆盖，此时正确做法是让调度器按序列长度决定是否跳过第二阶段、直接以 $\\mathcal{S}_1$ 进入后续层，把阈值与开关一起纳入请求级策略，而不是全局死守两阶段。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-11\">十一 · 两阶段筛选的边界条件与系统代价</h3>\n<p>把双阶段管线拆到算子粒度看，第一阶段是纯视觉侧的无梯度筛选：ViT 输出全部 patch token 后，对每个 token 取空间邻域内最大相似度，低于阈值 τ₁ 才保留，即 <span class=\"formula\">$$\\mathcal{S}_1=\\{j\\mid \\max_{i\\in\\mathcal{N}(j)}\\mathrm{sim}(\\mathbf{v}_j,\\mathbf{v}_i)&lt;\\tau_1\\}$$</span>。这一步的输入是完整视觉 token 张量，输出是稀疏索引集合，代价落在 ViT 输出带宽与一次邻域归约上——它不减少 ViT 本身的算力，只减少后续拼接与传输的 token 数。真正的风险在于 τ₁ 的语义：相似度剔除假设“邻域内高度相似的 patch 携带冗余信息”，但细粒度文字、小目标、密集表格恰恰是低相似度与高相似度混杂的区域，一旦 τ₁ 偏松，第一阶段就把细节 token 连同冗余一起删掉，而这一删除发生在文本尚未进入、任务信号完全缺席的时刻，后续任何阶段都无法恢复。</p>\n<p>第二阶段在 LLM 前若干层之后插入打分逻辑，用浅层跨模态注意力分数做 TopK：<span class=\"formula\">$$\\mathcal{S}_2=\\mathrm{TopK}(\\{a_j\\},k),\\ j\\in\\mathcal{S}_1$$</span>。输入是第一阶段幸存 token 的注意力分数，输出是最终保留集合，代价是额外一次前向与调度开销——打分必须在浅层注意力计算完成后才能进行，意味着这部分层要对 S₁ 的全部 token 做完整的 QKV 计算，压缩收益要到后续层才兑现。因此存在一个明确的盈亏平衡点：设浅层打分的前向代价为 C_score、后续每层对保留 token 的节省为 ΔC·(N−N_eff)，只有当层数足够深、序列足够长时节省才盖过开销。短请求、单图少 token 的场景下，N_eff 与 N 差距有限，打分开销反而成为净负担，这正是该方案在短序列请求上占比更高的结构性弱点。</p>\n<p>两个阈值的一致性是最隐蔽的失效路径。第一阶段按 patch 相似度、第二阶段按任务显著性，两套判据彼此独立：一个在文本缺席时被判定为冗余而剔除的 token，可能在第二阶段本应是高注意力关键 token，但它已不在候选集 S₁ 中，TopK 无从选回。这种“两阶段标准不一致导致关键 token 在两阶段间被误删”的失败不会报错，只表现为 KV 上下文不足、答案细节缺失，且难以定位是 τ₁ 还是 τ₂ 的责任。跨任务部署时问题被放大：τ₁、τ₂ 需按任务重新校准，图像描述类任务容忍高压缩率，文档理解与图表问答则要求保守阈值；未重新校准直接迁移，精度回退几乎必然发生。</p>\n<table class=\"mini\"><thead><tr><th>阶段</th><th>输入</th><th>输出</th><th>主要代价</th><th>失效条件</th></tr></thead><tbody><tr><td>第一阶段（ViT 后）</td><td>全部视觉 token</td><td>集合 S₁</td><td>邻域相似度归约、ViT 输出带宽</td><td>τ₁ 偏松，细节 token 被误删</td></tr><tr><td>第二阶段（LLM 浅层）</td><td>S₁ 的跨模态注意力分数</td><td>TopK 集合 S₂</td><td>额外一次前向与调度开销</td><td>短请求上收益被开销抵消</td></tr><tr><td>后续层</td><td>S₂</td><td>KV 仅对保留 token 维护</td><td>KV 显存与带宽随 N_eff 线性下降</td><td>S₁/S₂ 判据不一致致上下文不足</td></tr></tbody></table>\n<p>工程判断上，这套机制的价值不在压缩率数字，而在训练与推理共享同一双阶段管线——阈值在训练期就参与梯度路径，推理期不再切换策略，避免了训练-推理压缩不匹配带来的精度回退。代价是部署侧必须把 τ₁、τ₂ 当作任务级配置而非全局常量，并为浅层打分预留调度槽位；对延迟敏感的短请求，应设最小 token 下限或按序列长度动态跳过第二阶段，把开销挡在盈亏平衡点之外。</p>\n<h3 id=\"alg-duet-vlm-two-stage-sec-12\">十二 · 第一阶段集合式筛选的逐项拆解</h3>\n<p>第一阶段的可实现形态是一个邻域最大值判据，而不是对全局做聚类。给定 ViT 输出的 patch 表示 $\\mathbf{v}_j$ 与空间邻域 $\\mathcal{N}(j)$，判据写成 $\\max_{i\\in\\mathcal{N}(j)}\\mathrm{sim}(\\mathbf{v}_j,\\mathbf{v}_i)&lt;\\tau_1$ 时保留。逐项看：$\\mathrm{sim}$ 通常取余弦相似度，因为 ViT patch 表示在 LayerNorm 之后方向信息比模长更稳定；邻域 $\\mathcal{N}(j)$ 取 patch 网格上的 8 邻域或膨胀后的 3×3/5×5 窗口，窗口大小直接决定粗筛粒度；取 max 而非均值是关键一步——均值会被邻域内一个差异大的 patch 拉低，导致边界 token 被误删，而 max 表达的是“只要邻域里有任何一个足够不同的邻居，这个 token 就携带不可由邻居重建的信息”。阈值 $\\tau_1$ 越高，保留越激进。</p>\n<p>推导的关键一步在于把“冗余”定义成可重建性而非相似性本身。若 $\\mathbf{v}_j$ 可由邻域线性组合近似，则残差 $\\lVert \\mathbf{v}_j-\\sum_i w_i\\mathbf{v}_i\\rVert$ 小于噪声尺度时，剔除它不改变后续层的输入分布；在权重取均匀且邻域内表示高度一致的前提下，该残差正比于 $1-\\max_i \\mathrm{sim}$。于是阈值判据成为残差判据的廉价代理，避免了每 token 解一次最小二乘。代价上，这一步只发生在编码器输出之后、文本拼接之前，计算量为 $O(|\\mathcal{V}|\\cdot|\\mathcal{N}|)$ 次点积，相对 ViT 前向可忽略；但它决定了进入 LLM 的序列长度下界，也就是后续所有 KV 显存与预填 FLOPs 的乘数因子。</p>\n<p>举例：一张被切成 1024 个 patch 的图像，若大片背景区域内部余弦相似度接近 1，则这些 patch 的邻域 max 相似度高于 $\\tau_1$ 而被整片剔除，保留集合 $\\mathcal{S}_1$ 可能只剩几百个 token；而文字边缘、细纹理处的邻域 max 相似度低，必然留下。这就是“编码器侧不再丢细节”的具体含义：剔除判据只看局部可重建性，不看任务相关性，因此不会因为文本没提到就删掉视觉上独特的区域。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-13\">十三 · 第二阶段 TopK 与注意力分数的口径</h3>\n<p>第二阶段在 LLM 前若干层之后取跨模态注意力分数 $a_j$，对 $\\mathcal{S}_1$ 内的 token 做 $\\mathrm{TopK}(\\{a_j\\},k)$。这里的口径问题比公式本身更重要：$a_j$ 应当是文本 query 对视觉 key 的注意力在多个 head、多个 query token 上的聚合。聚合方式决定筛选偏向——取 max over heads 会保留只被单一 head 关注的 token（通常是细粒度空间线索），取 sum 或 mean 则偏向被多数 head 共同关注的语义显著区域。工程上常用的是对文本 token 维求均值、对 head 维求 max，再对浅层若干层做加权累加，浅层权重更高，因为浅层注意力尚未被深层语义抽象稀释。</p>\n<p>关键推导在于 $k$ 与 $\\tau_1$ 的耦合。设第一阶段保留率为 $r_1=|\\mathcal{S}_1|/|\\mathcal{V}|$，第二阶段保留率为 $r_2=k/|\\mathcal{S}_1|$，则有效 token 数 $N_{\\text{eff}}=r_1 r_2|\\mathcal{V}|$。后续层的 KV 显存与注意力计算近似正比于 $N_{\\text{eff}}$（视觉部分）加上文本长度，因此两阶段压缩率是相乘而非相加的关系：单阶段要做到同样的 $N_{\\text{eff}}$，必须一次性做出更激进的判断，误差无法被另一阶段补偿。这正是双阶段在同等压缩率下精度更好的结构性原因，而不是调参运气。</p>\n<p>代价落在浅层：打分需要一次额外的前向读出，且这次前向必须等文本 token 拼入后才能算跨模态注意力，所以它把预填切成两段，中间插入一次同步与调度决策。对长视觉序列、长文本的请求，这次开销被后续层节省的 KV 计算摊薄；对短请求，固定开销占比上升。举例：文本只有十来个 token 的图文问答，浅层打分本身的前向与 kernel 启动开销可能与省下的后续层计算同量级，压缩收益被抵消——这是该算法在短序列上的已知边界。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-14\">十四 · 两阶段判据不一致的失效路径</h3>\n<p>公式里两个指示函数相乘的形式 $\\text{keep}_i=\\mathbb{1}[\\text{sim}(v_i,\\mathcal{N}(v_i))&lt;\\tau_1]\\cdot\\mathbb{1}[a_i^{(l)}&gt;\\tau_2]$ 隐含一个顺序约束：第二阶段只能在 $\\mathcal{S}_1$ 内选，无法召回第一阶段已删的 token。于是失效模式不是“选错”，而是“不可逆的误删”。若 $\\tau_1$ 在某任务上偏大，第一阶段删掉了视觉上重复但被文本强相关的 token（例如表格中重复出现的同一符号，语义上每个都对应不同的文本指代），第二阶段即使注意力分数很高也无从恢复，KV 上下文直接缺失，表现为答案漏项而非整体精度下降——这种回退难以定位，因为日志里看到的只是保留 token 数偏少。</p>\n<p>反向的不一致同样存在：若第一阶段过于保守、$\\mathcal{S}_1$ 很大，第二阶段的 TopK 成为唯一有效压缩，浅层打分的一次前向就白付了，且 $k$ 的选取承受全部精度压力。因此两个阈值必须联合校准而非独立调参：给定目标 $N_{\\text{eff}}$，先在验证集上固定 $r_1 r_2$ 的乘积，再在乘积约束下扫描 $r_1$ 的分配，观察精度曲线的平坦区。跨任务部署时这套校准必须重做，因为“局部可重建”的统计特性随图像域变化——文档扫描件与自然照片的 patch 相似度分布完全不同。</p>\n<p>工程判断上，可以把第一阶段做成可回滚的：保留被剔除 token 的索引与表示（不进入 KV，只留在显存的一个旁路缓冲），当第二阶段 TopK 的分数分布出现异常（例如最高分与第 $k$ 名分数差距过小，说明筛选边界模糊）时触发一次回填。这以少量显存换取了失效模式的可观测性，代价是旁路缓冲的带宽占用，需按请求形态决定是否开启。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-15\">十五 · 伪代码落到可实现</h3>\n<p>把两阶段写成可实现的调度单元，核心是把“打分前向”与“主前向”分离，并让 KV 分配发生在 $k$ 确定之后。思路如下（伪代码级，非可执行代码）：</p>\n<ul>\n<li>阶段 A：ViT 输出 $\\{\\mathbf{v}_j\\}$，按网格构造邻域索引，计算邻域 max 余弦相似度，得到布尔掩码 $\\text{keep}^{(1)}$，压缩为 $\\mathcal{S}_1$ 的索引张量。</li>\n<li>阶段 B：把文本 token 与 $\\mathcal{S}_1$ 的视觉 token 拼成序列，跑 LLM 前 $l$ 层，只保留最后一层（或加权几层）的跨模态注意力矩阵的视觉列，聚合成 $a_j$。</li>\n<li>阶段 C：对 $\\mathcal{S}_1$ 内的 $a_j$ 做 TopK 得索引 $\\mathcal{S}_2$，按 $\\mathcal{S}_2$ 重排视觉 token 并分配 KV 页；后续层只对 $\\mathcal{S}_2$ 与全部文本 token 计算。</li>\n<li>阶段 D：若开启旁路缓冲，把 $\\mathcal{S}_1\\setminus\\mathcal{S}_2$ 的表示写入旁路区，记录分数边界指标供回填判定。</li>\n</ul>\n<p>实现上的三个具体机制决定性能：其一，阶段 B 的注意力读出必须避免物化完整注意力矩阵，用分块 flash 式 kernel 只累加视觉列，否则打分本身就成为显存瓶颈；其二，阶段 C 的 KV 页分配要支持“先按 $\\mathcal{S}_1$ 预留、再按 $\\mathcal{S}_2$ 收缩”，否则连续批处理中不同请求的页表碎片化会吃掉压缩收益；其三，阶段 B 与阶段 C 之间的调度点是一次天然的批重组机会，可把已完成打分的请求与仍在预填的请求混批，掩盖同步开销。</p>\n<p>代价核算：阶段 B 的额外前向使预填 FLOPs 增加约 $l/L$ 的比例（$L$ 为总层数，$l$ 为浅层数），但后续 $L-l$ 层的注意力与 KV 写入按 $N_{\\text{eff}}/|\\mathcal{V}|$ 缩减；净收益为正的条件是缩减量超过浅层开销，这解释了为何长视觉序列受益、短序列受损。显存侧，KV 峰值由 $\\mathcal{S}_2$ 决定，但阶段 B 期间需同时持有 $\\mathcal{S}_1$ 的激活，峰值出现在阶段 B 末尾，容量规划应按此点而非按最终 KV 估算。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-16\">十六 · 与单阶段压缩的公式级差别</h3>\n<p>把单阶段方法写成同一记号下的特例，差别立刻显现：单阶段要么令 $\\mathcal{S}_1=\\mathcal{V}$（只在 LLM 侧按 $a_j$ 做 TopK），要么令 $\\mathcal{S}_2=\\mathcal{S}_1$（只在编码器侧按相似度剔除）。前者的问题是浅层注意力对细粒度视觉线索的分辨力有限，压缩率一高就丢任务相关信息；后者的问题是相似度判据与任务无关，压缩率受图像内容统计特性限制，遇到纹理密集图像几乎压不动。双阶段的乘积结构让每一阶段只承担自己擅长的判断：局部可重建性交给编码器后处理，任务相关性交给浅层注意力。</p>\n<p>与 ViTCoP 的公式级差别在于筛选次数与位置：ViTCoP 在预填前做一次文本相关性筛选与合并，判据同时含文本相关性与 token 间可合并性，是单次联合决策；DUET-VLM 把决策拆成两次、判据正交（相似度 vs 注意力），因此两次的阈值可以独立校准，代价是两次决策之间的信息不可逆丢失。这也意味着 DUET-VLM 的压缩率上限由两阶段判据的交集决定，而非任一单阶段判据的极限。</p>\n<p>稳定性来自训练与推理共享同一管线：训练时同样执行两阶段筛选并让梯度只流经保留 token，推理时的序列长度分布与训练一致，避免了“训练见全长、推理见压缩”造成的分布偏移。这一点的工程价值在量化配置叠加时更明显——NVFP4/FP8 下激活分布对序列组成敏感，压缩策略不一致会放大数值误差。</p>\n<p>容量规划上，$N_{\\text{eff}}$ 应作为一级指标进入 SLO 模型：设每 token 每层的 KV 字节数为 $b$、层数为 $L$、并发请求数为 $B$，则视觉 KV 显存约为 $B\\cdot L\\cdot b\\cdot N_{\\text{eff}}$，而预填延迟近似由 $|\\mathcal{V}|$ 的浅层部分与 $N_{\\text{eff}}$ 的深层部分分段构成。两个阈值的选择因此不是纯精度问题，而是把延迟预算在浅层打分与深层计算之间重新分配的问题；短请求上应倾向保守的 $\\tau_1$（少删、让第二阶段多承担），长请求上应倾向激进的 $\\tau_1$（早删、减少阶段 B 的注意力读出规模）。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-17\">十七 · 边界条件：阈值失配、短请求与两阶段判据打架</h3>\n<p>这套双阶段筛选的失效不是随机噪声，而是集中在三个可定位的结构性缺口上。第一是阈值迁移：<span class=\"formula\">$$\\mathcal{S}_1=\\{j\\mid\\max_{i\\in\\mathcal{N}(j)}\\mathrm{sim}(\\mathbf{v}_j,\\mathbf{v}_i)&lt;\\tau_1\\},\\quad \\mathcal{S}_2=\\mathrm{TopK}(\\{a_j\\},k),\\ j\\in\\mathcal{S}_1$$</span> 中 $\\tau_1$ 与 $k$ 都是任务相关量。换域部署时若沿用旧 $\\tau_1$，第一阶段会把细粒度文字、小目标、表格线这类“局部高相似但语义关键”的 patch 当作冗余剔除，而 $\\mathcal{S}_2$ 只能在 $\\mathcal{S}_1$ 的残集里做 TopK——误删发生在第二阶段之前，注意力分数再准也救不回来，且日志上表现为“压缩率正常、精度掉点”，定位成本高。第二是判据不一致：$\\mathrm{sim}$ 是空间邻域内的表示相似度，$a_j$ 是跨模态显著性，两者度量不同空间；当第一阶段把某个与邻域高度相似、却被文本查询强相关的 token 删掉时，两阶段之间就出现语义断层，后续层维护的 KV 上下文不足以支撑生成。</p>\n<p>第三是短请求的开销占比。第二阶段要求在 LLM 浅层插入打分逻辑，等价于在预填路径上多一次前向与一次调度同步；对图像 token 多、文本短的请求，这次前向的相对成本被摊薄，压缩收益明显；但对文本占主导、视觉 token 本就少的请求，打分开销与 kernel 启动、批内同步的固定成本会吃掉压缩带来的算力节省，端到端延迟不降反升。工程判断是：把“是否启用第二阶段”做成按请求形态的路由条件，而不是全局开关。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>触发条件</th><th>系统代价</th></tr></thead><tbody><tr><td>阈值未重校准</td><td>跨任务部署沿用旧 $\\tau_1$</td><td>精度回退，压缩率指标正常，难定位</td></tr><tr><td>判据不一致</td><td>相似度剔除误删文本强相关 token</td><td>KV 上下文不足，生成质量下降</td></tr><tr><td>短请求开销</td><td>视觉 token 少、文本为主</td><td>额外前向与调度开销抵消压缩收益</td></tr></tbody></table>\n<p>因此可实现的做法是把 $\\tau_1$ 与 $k$ 作为部署期标定参数，按任务族离线扫一遍“压缩率—精度”曲线并写入配置，同时记录每层实际保留的 $N_{\\text{eff}}=\\sum_i\\text{keep}_i$ 作为运行时健康指标；一旦 $N_{\\text{eff}}$ 偏离标定区间就触发回退到不压缩路径。这套边界决定了 DUET-VLM 适合长视觉上下文、批大小可调的在线服务，而不适合视觉 token 极少的短问答场景。</p>\n<h3 id=\"alg-duet-vlm-two-stage-sec-18\">十八 · 请求形态：什么样的输入让两阶段真正省</h3>\n<p>DUET-VLM 的两阶段筛选在结构上要求“先有冗余、后有显著性可分”。第一阶段的判据是 patch 间相似度，$$\\mathcal{S}_1 = \\{j \\mid \\max_{i\\in\\mathcal{N}(j)} \\mathrm{sim}(\\mathbf{v}_j,\\mathbf{v}_i) &lt; \\tau_1\\}$$，它只在视觉 token 之间存在大量近邻重复时才产生收益；第二阶段的判据是浅层跨模态注意力分数 $a_j$ 上的 TopK，它只在文本查询与视觉 token 之间存在可分辨的显著性分布时才产生收益。这两条前提共同刻画了理想请求形态：单图或少量图、图像内容有明确主体与大面积同质背景、文本问题指向图像中的具体区域或属性。高分辨率文档扫描、图表、密集小字场景属于另一类：patch 间相似度低（笔画密集），$\\tau_1$ 下能剔除的比例小，第一阶段几乎不省；但这类请求恰恰是视觉 token 数最多的，于是压缩收益最需要的地方反而最弱。这是负载配方里最需要提前判断的一条。</p>\n<p>请求形态还决定第二阶段的打分成本能否被摊薄。打分逻辑插在 LLM 浅层，需要对拼接后的序列做一次额外前向与调度，其开销与序列长度近似线性。图像 token 占比越高、文本越短，这次前向的绝对代价越大，而可压缩的 token 也越多，两者同向增长；反之，纯文本或极短图像描述请求里，打分开销固定存在而可压缩量趋近于零。工程判断是：把“图像 token 数 / 总序列长度”作为一个路由特征，低于某个比例时直接走不压缩路径，避免为几乎无收益的请求支付浅层打分。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-19\">十九 · 长度分布：压缩率与开销的交叉点</h3>\n<p>设原始视觉 token 数为 $N_v$，第一阶段保留比例为 $r_1 = |\\mathcal{S}_1|/N_v$，第二阶段在 $\\mathcal{S}_1$ 上取 TopK 得 $k$，有效 token 数 $N_{\\text{eff}} = \\sum_i \\text{keep}_i$。后续层只对 $N_{\\text{eff}}$ 个 token 计算并维护 KV，因此解码阶段的 KV 显存与注意力带宽大致按 $N_{\\text{eff}}/N_v$ 缩放；而预填阶段多出的一次浅层打分前向，代价约为 $c \\cdot (N_v + N_t)$，其中 $N_t$ 为文本 token 数。压缩净收益可以写成</p>\n<div class=\"formula\">$$G \\approx \\alpha\\,(N_v - N_{\\text{eff}}) - c\\,(N_v + N_t)$$</div>\n<p>$\\alpha$ 是每剔除一个视觉 token 在后续层节省的计算与带宽折算系数。$G&gt;0$ 要求 $N_v$ 足够大且 $N_{\\text{eff}}/N_v$ 足够小。这解释了长度分布上的非单调性：短序列请求（单张小图、短问句）里 $N_v$ 小，$c(N_v+N_t)$ 相对占比高，$G$ 可能为负；中等长度、图像 token 占主导的请求 $G$ 最大；超长多图请求则受第二阶段 TopK 的 $k$ 上限约束，$N_{\\text{eff}}$ 不再随 $N_v$ 增长而线性下降，收益增速放缓但 KV 节省仍然显著。负载配方应当按 $N_v$ 分桶而不是按总 token 数分桶，因为决定收益的是视觉侧的可压缩量。</p>\n<p>具体例子：一张含大面积纯色背景的商品图，主体居中，文本问题为“这是什么颜色”。第一阶段在背景 patch 上大量命中 $\\tau_1$，$r_1$ 明显偏低；第二阶段注意力集中在主体区域，TopK 进一步收缩。此时 $N_{\\text{eff}}$ 远小于 $N_v$，KV 显存与解码带宽同步下降，收益体现在长输出场景的持续解码上。相反，同一张图配一个需要逐字读取标签的问题，浅层注意力分散到大量小字 patch，TopK 保留数上升，$N_{\\text{eff}}$ 逼近 $N_v$，收益退化为仅剩第一阶段的部分剔除。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-20\">二十 · 并发与批大小：打分开销在批维上的摊薄</h3>\n<p>第二阶段的浅层打分是一次独立前向，它在连续批处理中占据一个调度槽位。批内请求的 $N_v$ 差异越大，这次前向的时长越受最长请求支配，短请求被迫等待，形成队头阻塞。连续批处理框架按 token 预算组批时，若把打分前向与主前向混在同一批次，调度器需要为打分阶段单独预留预算，否则会出现批内部分请求已进入后续层、部分仍在打分的流水空洞。工程上更稳的做法是把打分前向作为独立微批提交，按 $N_v$ 排序后组批，使同一微批内长度接近，减少空转。</p>\n<p>批大小对收益的影响是双向的。批越大，单位时间内可摊薄的固定调度开销越多，打分前向的启动成本被稀释；但批越大，KV 显存占用越高，而 DUET-VLM 的 KV 节省正是靠 $N_{\\text{eff}}$ 缩小来实现的——两者在同一显存池里竞争。设批内平均有效 token 数为 $\\bar{N}_{\\text{eff}}$，KV 显存近似正比于 $B \\cdot \\bar{N}_{\\text{eff}} \\cdot L$（$L$ 为层数）。压缩把 $\\bar{N}_{\\text{eff}}$ 压低后，可以支撑更大的 $B$，从而把吞吐推上去；但如果为了追求 $B$ 而放松 $\\tau_1$、抬高 $k$，$\\bar{N}_{\\text{eff}}$ 回升，KV 又回到紧张状态。负载配方的核心是固定 SLO 下的三元平衡：$B$、$\\bar{N}_{\\text{eff}}$、打分开销，三者不能同时最优。</p>\n<p>并发层面的另一个代价是调度抖动。打分前向的时长随 $N_v$ 波动，在高低峰混合的流量里会造成批次完成时间方差变大，进而影响 TTFT 的尾延迟。把打分前向与主前向解耦、允许打分结果进入一个小容量队列等待主前向消费，可以吸收这种抖动，代价是引入额外的一次 token 驻留显存。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-21\">二十一 · 负载不对时的三种失效</h3>\n<p>第一种是阈值未随任务重校准。两个阈值 $\\tau_1$、$\\tau_2$（或等价的 $k$）按任务调参，跨任务部署时不重新校准，第一阶段会在新任务上剔除过多细节 token：相似度判据对“看起来相似但语义不同”的 patch 无分辨力，密集文字、细粒度图表里被误删的 token 在第二阶段已不可恢复，因为 $\\mathcal{S}_2$ 只在 $\\mathcal{S}_1$ 内取 TopK。精度回退表现为答案缺项而非明显错误，难以定位到具体阶段，这是最隐蔽的失效。</p>\n<p>第二种是短请求上收益被开销抵消。打分逻辑增加一次前向与调度开销，在 $N_v$ 小的请求上 $G&lt;0$，端到端延迟反而高于不压缩基线。这类请求在真实流量里占比往往不低（缩略图、单行问答），如果不做路由分流，整体 P99 会被拖累。</p>\n<p>第三种是两阶段判据不一致导致关键 token 在两阶段间被误删。第一阶段按空间邻域相似度保留，第二阶段按跨模态注意力取 TopK，两者标准不同：一个 token 可能因邻域相似度低而被保留，却在 TopK 中因注意力分数不足被丢弃，而它恰是后续层需要的上下文。KV 上下文不足表现为长答案生成中途失去视觉依据，输出前后矛盾。缓解手段是让第二阶段在 $\\mathcal{S}_1$ 上保留一个注意力分数下限而非纯 TopK，或在两阶段之间传递一个保底集合。</p>\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>第一阶段行为</th><th>第二阶段行为</th><th>系统代价</th></tr></thead><tbody><tr><td>大背景、单主体</td><td>高剔除率</td><td>注意力集中，TopK 小</td><td>KV 与解码带宽显著下降</td></tr><tr><td>密集文字/图表</td><td>低剔除率</td><td>注意力分散，TopK 大</td><td>打分开销照付，收益接近零</td></tr><tr><td>短请求、小图</td><td>剔除量小</td><td>TopK 相对序列占比高</td><td>延迟被打分前向拖高</td></tr><tr><td>多图长请求</td><td>按图分别剔除</td><td>受 $k$ 上限约束</td><td>KV 节省大，打分时长受最长图支配</td></tr></tbody></table>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-22\">二十二 · 配方落地：路由、分桶与阈值绑定</h3>\n<p>把上述判断写成可执行的负载配方，需要三个绑定关系。第一，路由绑定：以图像 token 占比与 $N_v$ 为特征，低于阈值直接走不压缩路径，高于阈值走双阶段；路由本身不引入前向，只做计数与比例判断。第二，分桶绑定：按 $N_v$ 分桶组批，同桶内 $\\tau_1$ 与 $k$ 取同一组值，避免批内阈值分裂导致的有效 token 数方差。第三，阈值绑定：$\\tau_1$、$k$ 与任务标识一起版本化，跨任务部署时强制重新校准并在离线集上验证 $N_{\\text{eff}}$ 分布，而不是沿用旧值。</p>\n<p>与 ViTCoP 的差别在这里体现为负载适配性：ViTCoP 只在预填前做一次文本相关性筛选与合并，判据单一，跨任务时只需校准一个相关性阈值；DUET-VLM 的两阶段判据各自独立，负载配方必须同时约束两个阶段的行为，否则第一阶段误删的 token 无法被第二阶段救回。这也意味着 DUET-VLM 的负载配方比单阶段方案更依赖任务画像，通用性换来了更高的压缩率上限。</p>\n<p>最后落在工程判断上：负载配方的正确性不体现在平均压缩率，而体现在 $N_{\\text{eff}}$ 分布的稳定性。若某任务下 $N_{\\text{eff}}/N_v$ 的方差随并发上升而扩大，说明打分前向的批内长度失配已经传导到有效 token 数，此时应先修组批策略再调阈值；若方差稳定但均值偏高，说明 $\\tau_1$ 或 $k$ 对新任务过松，应重新校准。把这两个观测量作为上线前的必查项，比任何单点吞吐数字都更能说明双阶段管线在该负载上是否成立。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-23\">二十三 · 短请求与长视觉序列下的收益反转</h3>\n<p>DUET-VLM 的净收益取决于“省下来的 KV 计算量”与“第二阶段固定开销”的比值。第二阶段必须在 LLM 浅层插入打分逻辑，这意味着无论最终保留多少 token，都要先走一遍前若干层并产出跨模态注意力分数 <span class=\"inline-math\">a_j</span>，再执行 <span class=\"inline-math\">\\(\\mathcal{S}_2=\\mathrm{TopK}(\\{a_j\\},k)\\)</span>。对图像 token 少、文本短的请求，<span class=\"inline-math\">\\(|\\mathcal{S}_1|\\)</span> 本来就小，后续层省下的算力有限，而这次额外前向与调度开销是刚性的，压缩收益被抵消。判断是否划算可用一个粗略的收支比：设后续层每 token 的 KV 维护代价为 <span class=\"inline-math\">c</span>，打分开销为 <span class=\"inline-math\">C_s</span>，则需 <span class=\"inline-math\">\\(c\\cdot(|\\mathcal{S}_1|-k) > C_s\\)</span> 才进入正收益区。工程上应把短请求路由到单阶段或不做压缩的路径，只在视觉 token 规模足够大、解码长度足够长时才启用双阶段。</p>\n<p>长度分布的另一端同样危险。请求形态是图像加文本的 VLM 请求，两个阈值按任务调参；若负载中图像分辨率高、patch 数多，第一阶段按空间邻域相似度剔除 <span class=\"inline-math\">\\max_{i\\in\\mathcal{N}(j)}\\mathrm{sim}(\\mathbf{v}_j,\\mathbf{v}_i)<\\tau_1</span> 会保留大量低冗余 token，<span class=\"inline-math\">\\(\\mathcal{S}_1\\)</span> 偏大，第二阶段的 TopK 才真正起作用，此时压缩率主要由 <span class=\"inline-math\">k</span> 决定而非 <span class=\"inline-math\">\\(\\tau_1\\)</span>，两个阈值的调参自由度退化为一个。反之，若负载以低分辨率、密集重复图案为主，<span class=\"tau_1\">\\(\\tau_1\\)</span> 过松会让第一阶段几乎不删，双阶段退化成单阶段加额外开销。</p>\n<table class=\"mini\"><thead><tr><th>负载形态</th><th>主要风险</th><th>系统代价落点</th></tr></thead><tbody><tr><td>短文本+小图</td><td>打分开销吃掉压缩收益</td><td>延迟，TTFT 上升</td></tr><tr><td>长文本+高分辨率</td><td>两阈值耦合，调参空间塌缩</td><td>显存，KV 驻留偏高</td></tr><tr><td>跨任务混部</td><td>阈值未重校准，细节 token 被误删</td><td>精度回退，难以定位</td></tr></tbody></table>\n<p>并发与批大小改变的是失效的可见度而非失效本身。连续批处理下不同请求的 <span class=\"inline-math\">\\(|\\mathcal{S}_1|\\)</span> 与 <span class=\"inline-math\">k</span> 各不相同，第二阶段打分逻辑在批内产生长度不齐的中间张量，调度器要为这次额外前向单独切分计算图，批越大，切分与同步的固定成本越容易被摊薄，但批内最长请求仍决定这一步的完成时间，短请求被迫等待。更隐蔽的是跨任务混部：两个阈值未按任务重新校准，第一阶段剔除过多细节 token，关键 token 在两阶段间被误删，KV 上下文不足，精度回退且难以定位到是哪一级筛选造成的。因此部署时应按任务分组、分组内固定阈值，并把 <span class=\"inline-math\">\\(\\tau_1\\)</span>、<span class=\"inline-math\">\\(\\tau_2\\)</span> 与 <span class=\"inline-math\">k</span> 作为容量规划的一等参数纳入 SLO 预算，而不是当作静态超参。</p>\n<h3 id=\"alg-duet-vlm-two-stage-sec-24\">二十四 · 硬件档位：按“两段前向”拆资源，而不是按整卡规格挑</h3>\n<p>DUET-VLM 的部署成本结构由两段前向决定：ViT 段是密集的 patch 计算，第二阶段是在 LLM 浅层插入的一次打分前向。后者不产出最终 logits，只产出跨模态注意力分数 $a_j$，因此它对算力要求低、对调度与显存带宽要求高。硬件选型的第一条判断是：不要把两段前向压在同一张卡的同一条执行流上串行排队，否则第二阶段那一次额外前向会直接叠加到首 token 延迟上。工程上可用的档位划分是三类：ViT 段与打分前向放同一卡组、后续层放另一卡组（预填/解码分离式拓扑的变体）；全部放单卡但用两路 CUDA 流让打分前向与文本嵌入搬运重叠；以及在 NVL72 机柜内把打分前向放到与 ViT 同域的 GPU、把长序列解码放到跨 NVLink 域的 GPU。三种档位的取舍点不在峰值算力，而在第二阶段那一次前向的调度开销能否被重叠掉。</p>\n<p>打分前向的代价可以用一个简单的下界刻画。设视觉 token 数为 $N_v$、文本 token 数为 $N_t$、LLM 浅层参与打分的层数为 $L_s$，则第二阶段额外计算量近似正比于 $L_s \\cdot (N_v+N_t)^2 \\cdot d$（注意力项）加上 $L_s\\cdot(N_v+N_t)\\cdot d^2$（投影项），其中 $d$ 为隐藏维。当 $N_v \\gg N_t$ 时，二次项主导，打分前向的开销随视觉 token 数平方增长；这正是必须在第一阶段先把 $N_v$ 压到较小值再进 LLM 的原因。反过来，当请求是短文本加小图、$N_v$ 与 $N_t$ 同量级时，二次项不占优，打分前向的固定调度开销（kernel 启动、跨流同步、批内 barrier）反而成为主项——这是短请求上压缩收益被抵消的机制来源，也是档位选择必须区分长序列与短序列的原因。</p>\n<p>具体例子：一个 8 卡节点上部署 72B 级 VLM，ViT 段与打分前向占 2 卡、后续层预填占 4 卡、解码占 2 卡。第一阶段把 $N_v$ 从全量 patch 压到 $N_{\\text{eff}}$，第二阶段在这 2 卡上以较小批执行打分，后续 6 卡只见保留 token。这样第二阶段的开销被限制在一个小资源池内，不污染解码路径的 SLO。若把打分前向塞进解码卡，则每个请求多一次前向同步，解码步的尾延迟被拉长，连续批处理的批间隔抖动变大。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-25\">二十五 · 并行拓扑：TP 跟着打分前向走，PP 跟着保留 token 的 KV 走</h3>\n<p>拓扑设计的第一原则是：张量并行（TP）的切分维度要覆盖打分前向的注意力头，因为 $a_j$ 是跨模态注意力分数，按头切分后需要一次 all-reduce 才能得到完整的显著性排序。若 TP 度过大而单请求视觉 token 很少，all-reduce 的固定延迟会超过打分本身的计算时间；若 TP 度过小，打分前向的单卡显存又要容纳完整注意力矩阵。工程判断是让打分前向的 TP 度与 ViT 段的 TP 度一致，避免在阶段边界做重切分（re-shard），因为重切分意味着一次全量 token 的跨卡搬运，代价正比于 $N_v \\cdot d$ 的字节数。</p>\n<p>流水并行（PP）的切分点应落在“保留 token 确定之后”。第二阶段结束、$N_{\\text{eff}}$ 确定，后续层的 KV 只为这 $N_{\\text{eff}}$ 个视觉 token 加文本 token 维护，显存占用从全量 $N_v$ 降到 $N_{\\text{eff}}$。把 PP 边界放在这里，可以让下游 stage 的 KV 分配按实际保留量做，而不是按最坏情况预留。若 PP 边界放在第二阶段之前，下游 stage 必须按 $N_v$ 上限预留 KV，显存浪费比例等于 $1-N_{\\text{eff}}/N_v$，在压缩率高的任务上这个浪费足以压低可并发批数。</p>\n<div class=\"formula\">$$\\text{KV}_{\\text{vis}} = 2 \\cdot L \\cdot N_{\\text{eff}} \\cdot d_{\\text{kv}} \\cdot b,\\quad \\text{浪费率} = 1 - \\frac{N_{\\text{eff}}}{N_v}$$</div>\n<p>其中 $L$ 为层数、$d_{\\text{kv}}$ 为每头 KV 维、$b$ 为字节数（FP8 为 1、BF16 为 2）、$2$ 表示 K 与 V。这个式子说明：KV 策略与并行拓扑是耦合的，PP 切分点选错会让压缩率无法转化为显存收益。具体例子：某任务 $N_v$ 为数千、$N_{\\text{eff}}$ 压到其几分之一，若 PP 边界在第二阶段之前，下游 stage 按 $N_v$ 预留，KV 池的有效容量被压缩率白白吃掉；把边界后移，同样的卡数可支撑更多并发请求，吞吐提升来自显存而非算力。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-26\">二十六 · 量化方案：分段量化，视觉段与打分前向不共享一套精度</h3>\n<p>量化不能对整条管线用同一套方案。ViT 段的激活分布随图像内容剧烈变化，patch 相似度比较对数值扰动敏感——第一阶段的判定是 $\\mathrm{sim}(\\mathbf{v}_j,\\mathbf{v}_i) &lt; \\tau_1$，若 $\\mathbf{v}$ 被量化到低精度，相似度在阈值附近的 token 会翻转判定，导致 $\\mathcal{S}_1$ 不稳定。因此视觉段宜保持较高精度（FP8 而非 NVFP4），或对相似度计算走一条不量化的旁路。打分前向的注意力分数 $a_j$ 只用于排序取 TopK，排序对绝对精度不敏感、对相对次序敏感，可以在 FP8 下执行；但 TopK 边界处的分数若被量化噪声打平，$k$ 个保留 token 的选取会出现抖动，进而让下游 KV 长度在请求间波动，破坏连续批处理的批形状稳定性。</p>\n<p>后续层是量化的主战场：保留 token 数量已固定，KV 以 FP8 存储可把 KV 显存减半，权重用 NVFP4 可降低权重带宽压力。这里的关键是量化方案要与 KV 策略一起定：若 KV 用 FP8，则第二阶段选出的 $a_j$ 排序必须在与 KV 精度一致的数值域里做，否则“按分数选 token”与“按低精度存 KV”之间的误差会叠加。工程上可复现的做法是：视觉段 FP8、打分前向 FP8 且 TopK 用 FP32 累加、后续层权重 NVFP4 加 KV FP8。这套组合让压缩判定稳定、让显存收益落在真正占大头的后续层 KV 上。</p>\n<p>代价方面，分段量化引入一次精度转换的边界搬运，视觉段输出从 FP8 转成打分前向的输入格式，字节量正比于 $N_v\\cdot d$；在短请求上这次搬运的相对开销更高。具体例子：同一模型在长文档图像任务上，KV FP8 让单卡可并发批数上升，吞吐受益明显；而在单张小图短问答上，KV 本就很小，FP8 收益被转换开销抵消，此时应关闭 KV 量化、保持打分前向的 FP32 累加以换取判定稳定。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-27\">二十七 · KV 策略：按 $N_{\\text{eff}}$ 分配、按阶段释放、按请求回收</h3>\n<p>KV 策略的核心是把“压缩后的长度”作为分配单位，而不是把“最大可能长度”作为预留单位。可复现的做法分三步：请求进入时按 $N_v$ 上限做一次临时预留，仅供第二阶段打分前向使用；第二阶段产出 $\\mathcal{S}_2$ 与 $N_{\\text{eff}}$ 后，立即把临时预留收缩到 $N_{\\text{eff}}+N_t$，多余块归还池；解码阶段按收缩后的长度做分页管理。这个顺序把峰值显存压在打分前向那一刻，而稳态显存由 $N_{\\text{eff}}$ 决定。若反过来先按 $N_{\\text{eff}}$ 分配再扩容，会在打分前向时触发块分配失败或抢占，连续批处理的批稳定性被破坏。</p>\n<p>释放时机同样重要。第二阶段打分前向产生的中间激活（注意力矩阵、分数向量）在 $\\mathcal{S}_2$ 确定后即可释放，不应带入后续层；否则这部分激活会与 KV 池争抢显存，压缩率带来的收益被中间态吃掉。工程上把打分前向的激活生命周期限定在“一次前向 + 一次 TopK”内，用显存池的即时回收保证后续层只看到保留 token 的 KV。</p>\n<p>失败模式在这里很具体：第一阶段相似度剔除与第二阶段注意力筛选标准不一致时，关键 token 在两阶段间被误删，KV 上下文不足——表现为解码阶段对图像细节的指代失败，而日志上只看到 $N_{\\text{eff}}$ 偏小。可复现的排查手段是记录每个请求的 $N_v$、$|\\mathcal{S}_1|$、$N_{\\text{eff}}$ 三元组，当 $|\\mathcal{S}_1|$ 相对 $N_v$ 的压缩比明显偏离校准值时，说明 $\\tau_1$ 在该任务上过激。具体例子：跨任务部署时若沿用旧任务的 $\\tau_1$，第一阶段把细节 token 大量剔除，第二阶段再准也无法找回，精度回退且难以定位——这正是需要按任务重新校准两个阈值的工程原因。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-28\">二十八 · 调度参数：批形状按 $N_{\\text{eff}}$ 分组，打分前向单独成批</h3>\n<p>连续批处理在 DUET-VLM 上要改一处：批内请求的视觉 token 数差异极大，若按请求到达顺序组批，第二阶段打分前向的批形状会被最长请求拖住，短请求等待长请求的打分完成，尾延迟被拉长。可复现的做法是按 $N_{\\text{eff}}$ 分桶组批：把压缩后长度接近的请求放进同一批，打分前向与后续层都按桶内形状执行。分桶粒度可用 $N_{\\text{eff}}$ 的对数区间，桶边界按校准时的压缩率分布确定。</p>\n<p>调度参数中与两阶段直接相关的是“打分前向的最大等待窗口”。第二阶段需要一次额外前向，若为每个请求单独发起，kernel 启动与同步开销在短请求上占比过高；若无限等待凑批，首 token 延迟被拉长。工程判断是给打分前向设一个以 token 数为单位的等待窗口：窗口内累积的视觉 token 总量达到阈值即发起，否则按超时发起。阈值取“一次打分前向的固定开销与单 token 计算量之比”对应的 token 数，使凑批收益刚好覆盖等待成本。这个参数与 $\\tau_1$、$\\tau_2$ 一起构成部署配方中需要按任务重校准的三元组。</p>\n<p>具体例子：图像问答任务中 $N_{\\text{eff}}$ 分布集中，分桶后批形状稳定，打分前向的等待窗口可以设得较长以换取更高批利用率；而在混合任务（小图短问 + 大图长文档）上，$N_{\\text{eff}}$ 分布跨度大，分桶会把批数打散，此时应缩短等待窗口、允许更多小批，用批数换尾延迟。代价是打分前向的固定开销被重复支付，吞吐下降，但 SLO 的尾延迟可控——这是调度参数在两类负载间的取舍点，不是靠单一配置通吃。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-29\">二十九 · 可复现配置思路：先定阈值、再定拓扑、最后定量化</h3>\n<p>把上述要素串成一个可复现的顺序：第一步在目标任务的校准集上固定 $\\tau_1$ 与 $\\tau_2$，记录 $N_v$、$|\\mathcal{S}_1|$、$N_{\\text{eff}}$ 的分布，得到压缩率与精度回退的权衡曲线；第二步按 $N_{\\text{eff}}$ 分布定分桶边界与打分前向等待窗口；第三步按 $N_{\\text{eff}}$ 的稳态显存需求定 PP 切分点与 KV 池容量；第四步才定量化方案，视觉段与打分前向保持 FP8、TopK 用 FP32 累加、后续层权重 NVFP4 与 KV FP8。顺序不能颠倒：先定量化会让阈值校准落在被量化扰动的相似度上，先定拓扑会让 KV 容量按错误的长度预留。</p>\n<p>这套顺序的工程含义是：DUET-VLM 的部署配方里，真正需要按任务重校准的是两个阈值与一个等待窗口，硬件档位与并行拓扑一旦按 $N_{\\text{eff}}$ 分布定下就相对稳定，量化方案则跟随 KV 策略。跨任务泛化失败的根因几乎总是第一步被跳过——沿用旧阈值直接上线，第一阶段剔除过多细节 token，第二阶段无法补救。可复现的判据是：新任务上 $|\\mathcal{S}_1|/N_v$ 与校准值的偏离超过设定带宽，即触发阈值重校准，而不是去调批大小或换卡。</p>\n<p>最后落在一个具体机制上：第二阶段打分前向的插入位置决定了整条配方的耦合关系——它既是精度保障（浅层跨模态注意力提供任务相关显著性），又是开销来源（一次额外前向与调度）。部署时把这个前向隔离到独立资源池、按 $N_{\\text{eff}}$ 分桶组批、用等待窗口控制凑批，就能让它的开销不污染解码路径的 SLO；而 $\\tau_1$ 与 $\\tau_2$ 的校准质量决定了 $N_{\\text{eff}}$ 是否可信，进而决定 KV 分配与 PP 切分点是否成立。配置的稳定性来自训练与推理共享同一双阶段管线这一事实：推理侧的阈值只需在该管线定义的判定域内校准，不需要为部署另造一套压缩逻辑。</p>\n<h3 id=\"alg-duet-vlm-two-stage-sec-30\">三十 · 两阶段筛选的显存账：KV 只对幸存者记账</h3>\n<p>DUET-VLM 的显存收益不是均匀摊在整条链路上的，而是集中在 KV cache 这一侧。机制上，第一阶段在 ViT 之后按 patch 间相似度做粗筛，得到集合 <span class=\"inline\">S₁</span>；第二阶段在 LLM 浅层用跨模态注意力分数做细筛，得到 <span class=\"inline\">S₂</span>；此后每一层只为 <span class=\"inline\">S₂</span> 中的 token 计算 K/V 并写入缓存。这意味着 KV 的条目数从 <span class=\"inline\">N</span> 降到 <span class=\"inline\">N_eff</span>，而每层 KV 占用与 <span class=\"inline\">N_eff</span> 成正比：</p>\n<div class=\"formula\">$$M_{\\text{KV}} \\approx 2 \\cdot L \\cdot H_{\\text{kv}} \\cdot d_{\\text{head}} \\cdot N_{\\text{eff}} \\cdot b \\cdot s$$</div>\n<p>其中 <span class=\"inline\">b</span> 是并发序列数、<span class=\"inline\">s</span> 是字节宽度。工程含义很直接：<span class=\"inline\">N_eff</span> 每降一档，可同时驻留的请求数就抬一档，而这是连续批处理吞吐的上限所在。但要注意两处不对称。其一，ViT 侧的激活与中间张量并不因第二阶段而缩小——第一阶段剔除的是 token 数，不是通道数或空间分辨率，编码器仍要跑完整的前向，这部分显存峰值与压缩率基本无关。其二，浅层打分需要保留未压缩的注意力图与分数向量，在第二阶段完成前，浅层激活仍按 <span class=\"inline\">N</span> 计。于是显存曲线呈现“先高后低”：浅层是峰值区，深层才回落。规模上去以后，第一个撞墙的往往不是 KV 容量，而是浅层激活峰值与 ViT 激活叠加后的瞬时占用。具体例子：一条 4k 视觉 token 的请求，若 <span class=\"inline\">N_eff</span> 压到 1k，深层 KV 省下约四分之三，但浅层打分那几层的激活仍按 4k 计，批大小受限于此而非 KV。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-31\">三十一 · 带宽与算力的错配：省下的是 HBM 流量，不是 MMA</h3>\n<p>解码阶段的瓶颈通常在 HBM 带宽而非张量核心吞吐。DUET-VLM 对带宽的削减来自两处：KV 读取量随 <span class=\"inline\">N_eff</span> 线性下降；后续层注意力的 QK^T 与 PV 的 K/V 侧访存同样按 <span class=\"inline\">N_eff</span> 缩减。用 roofline 的语言，单 token 解码的算术强度约正比于 <span class=\"inline\">N_eff</span>，因此压缩把工作点进一步推向带宽受限区：</p>\n<div class=\"formula\">$$I \\approx \\frac{2 \\cdot L \\cdot N_{\\text{eff}} \\cdot d}{M_{\\text{KV}}/b} \\;\\Rightarrow\\; \\text{时间} \\approx \\max\\!\\left(\\frac{\\text{FLOPs}}{P_{\\text{peak}}},\\ \\frac{\\text{Bytes}}{BW}\\right)$$</div>\n<p>问题在于省下的带宽并不自动转化为等比例的延迟下降。第二阶段插入的打分逻辑本身要在浅层做一次额外的注意力读取与前向，这部分开销与 <span class=\"inline\">N</span> 成正比而非与 <span class=\"inline\">N_eff</span> 成正比——它恰恰落在最贵的那一段。于是净收益取决于压缩比与打分成本的比值：当 <span class=\"inline\">N</span> 很大、<span class=\"inline\">N_eff/N</span> 很低时，深层省下的带宽远大于浅层多付的一次读取；当请求的视觉 token 本就少（单图、低分辨率、短文本），打分开销可能吃掉全部收益，这正是失败模式中“短请求上压缩收益被开销抵消”的量化来源。工程判断是：把打分逻辑与浅层注意力的 K/V 读取融合，避免为打分单独再读一遍 K/V，是这条管线能否在中小请求上站住的关键。另一个错配点是 MMA 利用率：<span class=\"inline\">N_eff</span> 变小后，单次注意力的矩阵形状变窄，tcgen05 的 tile 填充率下降，2-SM MMA 的配对收益也随之缩水，因此压缩率并非越高越好，存在一个与 tile 形状匹配的甜点区。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-32\">三十二 · 通信面：压缩发生在集合通信之前才有价值</h3>\n<p>在分离式预填/解码与张量并行的部署里，视觉 token 的压缩位置决定了它是否真的省通信。若压缩发生在预填节点内部、且在 KV 传输之前完成，那么 NIXL 搬运的 KV 块数与 <span class=\"inline\">N_eff</span> 成正比，预填到解码的 KV 传输量随之下降，这对分离式架构的尾延迟是直接利好。反之，若压缩在解码侧才发生，KV 已经按 <span class=\"inline\">N</span> 传过一遍，通信成本不变，只是解码算力略降。张量并行下还有一层：每层注意力的 all-reduce 或 reduce-scatter 规模与 token 数相关，<span class=\"inline\">N_eff</span> 缩小会减轻这些集合通信，但浅层打分那几层仍按 <span class=\"inline\">N</span> 通信，形成“前重后轻”的通信曲线。NVLink 5 的高带宽让单次传输不算贵，真正贵的是同步点：第二阶段的 TopK 选择是一个跨 token 的归约操作，在张量并行下需要跨 rank 交换分数才能做全局 TopK，这引入一次额外的同步与一次小消息通信。规模上去以后，这次同步的固定开销会在高并发下被放大成排队。工程上可行的做法是把 TopK 退化为按 rank 局部 TopK 再合并，牺牲少量全局最优性换取同步次数下降；或者把阈值 <span class=\"inline\">τ₂</span> 改为绝对阈值而非 TopK，把归约变成逐元素比较，彻底去掉跨 rank 同步。代价是 <span class=\"inline\">N_eff</span> 变得不可预测，批调度需要按最坏情况预留。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-33\">三十三 · 功耗与热：压缩改变的是功耗曲线的形状</h3>\n<p>功耗在推理系统里通常跟随利用率而非跟随 token 数，但 DUET-VLM 改变了功耗在时间轴上的分布。ViT 前向是持续的高算力段，浅层打分是“高带宽、低算力”的混合段，深层解码则是纯带宽段。压缩把深层段的每 token 能耗降下来，却把浅层段的能耗密度抬上去——因为打分要在原本就贵的浅层多读一次。整条请求的能耗大致可写成：</p>\n<div class=\"formula\">$$E \\approx E_{\\text{ViT}} + E_{\\text{score}}(N) + E_{\\text{decode}}(N_{\\text{eff}})$$</div>\n<p>其中 <span class=\"inline\">\\(E_{\\text{score}}\\)</span> 与 <span class=\"inline\">N</span> 同阶、<span class=\"inline\">\\(E_{\\text{decode}}\\)</span> 与 <span class=\"inline\">N_eff</span> 同阶。这解释了一个容易被忽略的现象：在功耗受限的部署（如 GB200 NVL72 机柜的功率封顶）下，压缩带来的吞吐提升可能小于预期，因为省下的是长尾的低密度功耗，而增加的是峰值段的高密度功耗，机柜的功率上限由峰值决定。对风冷或液冷边界而言，浅层打分段的瞬时功率密度更值得关注。工程判断是：把打分逻辑安排在 ViT 之后的空闲算力窗口、或与文本预填重叠执行，用时间上的错峰换取功率曲线上的削峰，比单纯追求压缩率更能提升机柜级吞吐。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-34\">三十四 · 尾延迟：阈值不确定性与两阶段不一致</h3>\n<p>平均吞吐好看不代表 SLO 达标，DUET-VLM 的尾延迟有三个独立来源。第一是 <span class=\"inline\">N_eff</span> 的方差：<span class=\"inline\">N_eff = Σ keep_i</span>，而 keep 由两个阈值与内容共同决定，图像内容差异会让不同请求的 <span class=\"inline\">N_eff</span> 相差数倍。连续批处理按 token 数做预算时，一个 <span class=\"inline\">N_eff</span> 偏大的请求会拖长整个批的迭代时间，尾延迟由此产生。第二是两阶段判据不一致导致的返工：第一阶段按空间邻域相似度剔除，第二阶段按注意力显著性选取，两者标准不同，若某关键 token 在第一阶段被误删，第二阶段无从恢复，模型只能在不完整上下文上作答——这不表现为延迟，而表现为精度回退且难以定位，属于最隐蔽的失败模式。第三是跨任务未重新校准阈值：<span class=\"inline\">τ₁</span> 偏松会在新任务上剔除过多细节 token，<span class=\"inline\">τ₂</span> 偏紧则保留过多、压缩率失效，两者都把尾延迟推向不可预测。缓解手段是把 <span class=\"inline\">N_eff</span> 纳入调度器的准入控制：对 <span class=\"inline\">N_eff</span> 估计偏大的请求单独成批或降级到不压缩路径，用确定性的上界换取尾延迟的稳定。规模上去以后，最先崩的通常不是显存也不是带宽，而是这个方差——它让容量规划从“按均值算”变成“按分位数算”，而分位数在跨任务混合流量下极难标定。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-35\">三十五 · 规模上限的排序：先崩的是调度，不是硬件</h3>\n<p>把五个维度放在同一张表里看，规模上去以后的崩溃顺序是可以排序的。显存与带宽是线性可预测的，压缩比确定后容量规划就是算术；通信在压缩前置的前提下同样可预测；功耗受峰值段约束，属于机柜级而非单卡级问题；真正非线性的是调度与阈值标定。下表给出各维度随规模增长的劣化形态与首个观测点。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>随规模的行为</th><th>先崩的位置</th><th>工程对策</th></tr></thead><tbody><tr><td>KV 显存</td><td>随 N_eff 线性，可预测</td><td>浅层激活峰值先于 KV 触顶</td><td>分阶段释放浅层激活，打分与注意力融合</td></tr><tr><td>HBM 带宽</td><td>深层线性下降，浅层不变</td><td>短请求上打分开销抵消收益</td><td>按 N 设压缩启用门槛</td></tr><tr><td>集合通信</td><td>压缩前置则线性下降</td><td>跨 rank TopK 的同步点</td><td>局部 TopK 合并或绝对阈值替代</td></tr><tr><td>功耗</td><td>峰值段密度上升</td><td>机柜功率封顶由浅层决定</td><td>打分与文本预填错峰</td></tr><tr><td>尾延迟</td><td>N_eff 方差随流量混合放大</td><td>批内长请求拖累整批</td><td>按 N_eff 上界做准入与分批</td></tr></tbody></table>\n<p>排序的结论是：在单机或单节点规模，DUET-VLM 的收益主要来自 KV 与带宽，代价是浅层激活与打分开销，两者都在可控范围内；跨节点、跨任务混合流量时，<span class=\"inline\">N_eff</span> 的方差与阈值标定成为第一约束，硬件反而退居其次。这也解释了为什么该算法把“训练与推理共享同一双阶段管线”当作稳定性技巧而非精度技巧——共享管线让 <span class=\"inline\">N_eff</span> 的分布在训练时就已被观测，推理侧的分位数标定才有依据；一旦训练与推理用不同压缩策略，<span class=\"inline\">N_eff</span> 分布漂移，尾延迟与精度同时失去可预测性。落地时的具体判断是：先固定 <span class=\"inline\">τ₁</span> 让第一阶段只做保守剔除，把压缩率的主要来源交给第二阶段的注意力显著性，因为后者与任务相关、可随流量在线观测；再以 <span class=\"inline\">N_eff</span> 的 P99 而非均值作为批调度预算，把方差挡在准入层而不是让它进入批内。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-36\">三十六 · 双阶段管线的系统代价：从短请求到规模上限</h3>\n<p>把双阶段压缩放进真实推理栈，代价不是均匀分布的。第一阶段在 ViT 之后按邻域相似度剔除，只动视觉侧张量，不触碰 KV；第二阶段要在 LLM 前若干层插入打分逻辑，意味着这些层必须对<b>全部</b>拼接后的 token 做一次跨模态注意力前向，才能得到 $a_j$ 并执行 $\\mathcal{S}_2=\\mathrm{TopK}(\\{a_j\\},k)$。于是每请求的预填算力近似为 $C_{\\text{prefill}}\\approx C_{\\text{full}}(L_s)+C_{\\text{kept}}(L-L_s)$，其中 $L_s$ 是打分所在浅层深度、$C_{\\text{full}}$ 为未压缩前向成本。$L_s$ 越大，打分越准但开销越高；$L_s$ 越小，压缩越早、KV 峰值越低。这条权衡直接决定显存曲线：KV 占用按 $N_{\\text{eff}}=\\sum_i \\text{keep}_i$ 线性缩放，而打分阶段的激活与临时缓冲仍按原始 token 数分配，因此显存峰值出现在第二阶段结束前，而非稳态解码期。</p>\n<p>带宽与通信的账要分开算。视觉 token 缩减降低的是 HBM 读写与 KV 分页流量，收益随批大小放大；但打分逻辑本身是一次额外的调度与内核启动，在短序列请求（单图、短 prompt）上固定开销占比高，压缩收益被抵消——这正是该方案在低延迟场景的失效条件。跨任务部署时若两个阈值未重新校准，第一阶段按 $\\tau_1$ 剔除过多细节 token，第二阶段又在残缺集合上取 TopK，关键 token 在两阶段间被误删，KV 上下文不足导致精度回退且难以定位，因为错误发生在两套不一致的筛选标准交界处。</p>\n<table class=\"mini\"><thead><tr><th>规模维度</th><th>先崩的位置</th><th>机制</th></tr></thead><tbody><tr><td>批大小上升</td><td>打分阶段激活显存</td><td>临时缓冲按原始 token 数分配，先于 KV 触顶</td></tr><tr><td>序列变短</td><td>尾延迟</td><td>固定前向与调度开销摊薄不掉</td></tr><tr><td>跨任务混布</td><td>精度而非吞吐</td><td>阈值失配，两阶段筛选标准冲突</td></tr></tbody></table>\n<p>尾延迟的来源是第二阶段的位置：它把一次完整前向插在预填关键路径上，P99 由最慢的那批请求决定，而打分成本与图像 token 数正相关，长图请求天然拖尾。功耗侧，浅层全量前向的 Tensor Core 占用时间不随压缩率下降，压缩只削减后续层的算力与 KV 带宽，因此能效改善滞后于吞吐改善。工程判断是：把 $L_s$ 压到最浅可行层、让打分与第一阶段共享同一份 token 布局以减少重排，并按任务族维护阈值表而非全局单阈值；当请求以短序列为主时，应关闭第二阶段或退化为单阶段，因为此时 $\\mathcal{S}_2$ 的边际收益低于其固定开销。</p>\n<h3 id=\"alg-duet-vlm-two-stage-sec-37\">三十七 · 阈值漂移：跨任务精度回退的定位方法</h3>\n<p>DUET-VLM 的两个阈值不是超参数，而是任务契约。$\\tau_1$ 决定第一阶段按 patch 邻域相似度剔除多少视觉 token，$\\tau_2$（或等价的 TopK 的 $k$）决定第二阶段用浅层跨模态注意力留下多少。失败模式中最隐蔽的一种是：模型在源任务上校准好阈值后直接搬到新任务，第一阶段就把承载判别信息的细节 patch 当作冗余剔除，后续层再努力也补不回来。这类精度回退之所以难定位，是因为它表现为\"整体略降\"而非\"某类样本崩掉\"，工程师容易误判为量化误差或采样噪声。</p>\n<p>可操作的诊断路径是把压缩率拆成两段可观测的量：$r_1=|\\mathcal{S}_1|/N$ 与 $r_2=|\\mathcal{S}_2|/|\\mathcal{S}_1|$，并分别按任务标签分桶统计。若某任务桶的 $r_1$ 显著低于源任务基线而 $r_2$ 正常，问题在第一阶段；若 $r_1$ 正常但 $r_2$ 偏高（保留过少），问题在第二阶段打分。进一步，对回退样本做\"阈值回放\"：固定模型权重，仅把 $\\tau_1$ 下调一档重跑同一批请求，若精度恢复，则确认是第一阶段的过度剔除。这个实验的成本很低——只需重跑 ViT 与浅层，不涉及后续层 KV 维护，显存占用远小于完整前向。</p>\n<p>工程判断上，跨任务部署必须把阈值校准当作上线门槛而非调优项。校准集不必大，但必须覆盖该任务的长尾视觉形态（小目标、密集文本、细粒度图表），因为这些正是相似度剔除最容易误伤的 patch 类型。校准产出的不应是单一标量，而是\"任务—阈值\"映射表，随请求的任务标签路由到对应阈值。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-38\">三十八 · OOM 的三个来源与显存核算</h3>\n<p>DUET-VLM 的显存失败很少来自权重，而来自三个阶段的同时驻留：ViT 输出的全量视觉 token、LLM 浅层为打分而保留的中间激活、以及后续层按 $\\mathcal{S}_2$ 维护的 KV。第一阶段剔除发生在 ViT 之后，但 ViT 本身仍要产出全部 token，这部分峰值无法通过压缩消除。第二阶段打分需要一次额外前向，其激活在打分完成前不能释放。真正的风险点是批内请求的压缩率不一致：一个几乎无冗余的图像（$r_1\\approx 1$）与一个高冗余图像同批时，KV 预算按均值估算就会溢出。</p>\n<div class=\"formula\">$$M_{\\text{kv}} \\approx B\\cdot L\\cdot \\bar{N}_{\\text{eff}}\\cdot d\\cdot b,\\quad \\bar{N}_{\\text{eff}}=\\frac{1}{B}\\sum_{b}\\sum_i \\text{keep}_i^{(b)}$$</div>\n<p>其中 $B$ 为批大小、$L$ 为后续层数、$d$ 为头维展开后的宽度、$b$ 为每元素字节数。$\\bar{N}_{\\text{eff}}$ 用批均值会让方差大的批次出现尖峰。诊断手段是给每个请求记录 $N_{\\text{eff}}$ 并计算批内极差；当极差超过阈值时，调度器应改为按 $N_{\\text{eff}}$ 分桶组批，而不是按请求到达顺序组批。代价是组批等待带来的排队延迟，但在长视觉序列请求上，这个交换通常划算——OOM 触发的重试与降级代价远高于几十毫秒的等待。</p>\n<p>另一个常被忽略的来源是打分逻辑的临时缓冲：第二阶段要在浅层插入打分，需要保留跨模态注意力分数用于 TopK，这部分内存在短请求上占比更高，因为固定开销被摊薄得少。监控上应把\"打分缓冲峰值\"与\"KV 峰值\"分开打点，否则 OOM 时无法判断该降批还是该降 $k$。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-39\">三十九 · 批抖动与路由不均：两个不同的问题</h3>\n<p>批抖动指同一批内请求的 $N_{\\text{eff}}$ 差异导致的有效计算量波动，表现为吞吐随批次组成剧烈起伏，而 GPU 利用率曲线呈锯齿。它的根因是压缩率与内容强相关：文本密集的图表请求保留 token 多，纯色背景的产品图保留 token 少。诊断方法是把每批的 $\\sum_b N_{\\text{eff}}^{(b)}$ 与批大小 $B$ 一起打点，画散点图；若相关性弱，说明组批策略失效。</p>\n<p>路由不均则是另一个层面的问题：在分离式部署或跨阶段并行服务中，请求按任务标签或长度路由到不同实例，而不同任务的典型压缩率不同，导致某些实例的 KV 压力系统性偏高。这与批抖动不同——前者是批内方差，后者是实例间均值偏移。诊断上要按实例维度统计 $r_1$、$r_2$ 与尾延迟，若某实例的 $r_2$ 持续偏低（保留 token 多），说明路由把高细节任务集中到了它身上。修复不是调阈值，而是改路由权重，让压缩率高的任务与压缩率低的任务按比例混布。</p>\n<p>代价层面，路由不均的直接后果是集群级的显存碎片化：部分实例提前触顶而降批，另一些实例空闲。这种不均衡在尾延迟上放大得比均值吞吐更明显，因为降批实例的排队长度会自我强化。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-40\">四十 · 尾延迟尖刺：打分开销与短请求的错配</h3>\n<p>第二阶段在 LLM 浅层插入打分逻辑，增加一次前向与调度开销。这个开销在长序列请求上被压缩收益覆盖，但在短请求上占比高——视觉 token 少、文本短、后续层计算本来就轻，打分那一次额外前向成了主导项。尾延迟尖刺的典型形态是：P50 正常，P99 突然抬升，且抬升样本集中在短请求桶。</p>\n<p>诊断需要把延迟拆成\"ViT 段 / 第一阶段剔除 / 浅层打分 / 后续层 KV\"四段打点，并按输入 token 总数分桶。若短请求桶中打分段的占比超过剔除段节省的时间，则该请求的净收益为负。工程上的处理不是全局关掉第二阶段，而是按请求长度做条件分支：低于某长度阈值的请求跳过细粒度二次压缩，直接沿用第一阶段的 $\\mathcal{S}_1$。这引入了一个新的不一致——训练时管线是固定的两阶段，推理时短请求走单阶段——因此必须验证该分支下的精度不回退，通常做法是在校准阶段就显式评估这条捷径路径。</p>\n<p>另一个尖刺来源是打分逻辑与调度器的交互：打分需要一次同步点才能拿到注意力分数做 TopK，若调度器在此期间无法插入其他请求的计算，就形成气泡。缓解方式是把打分与下一批的 ViT 计算重叠，代价是显存中同时驻留两组激活。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-41\">四十一 · 两阶段标准不一致导致的误删</h3>\n<p>最严重的失败模式是第一阶段与第二阶段的筛选标准不一致：第一阶段按空间邻域相似度剔除，第二阶段按跨模态注意力显著性保留，两者若没有共享的语义基准，关键 token 可能在第一阶段被当作冗余删掉，而第二阶段根本看不到它。表现为 KV 上下文不足——模型回答时缺少必要的视觉证据，但压缩率指标看起来完全正常。</p>\n<p>诊断这类问题不能只看压缩率，要看\"被删 token 的注意力质量\"。做法是在校准集上记录每个被第一阶段剔除的 token 在浅层跨模态注意力中的分数分布；若存在一批被删 token 的分数显著高于保留 token 的中位数，说明两阶段标准冲突。$\\mathcal{S}_1$ 的定义 $\\max_{i\\in\\mathcal{N}(j)}\\mathrm{sim}(\\mathbf{v}_j,\\mathbf{v}_i)&lt;\\tau_1$ 只保证局部冗余，不保证任务无关，这正是冲突的根源。</p>\n<p>修复手段是给第一阶段加一个保守下界：对相似度接近阈值的边界 token 不做剔除，留给第二阶段裁决。代价是 $r_1$ 上升、第一阶段收益下降，但换来了两阶段标准的一致性。这个下界本身需要按任务校准，属于阈值表的一部分。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-42\">四十二 · 监控指标与回滚策略</h3>\n<p>监控应围绕四个量构建：分段压缩率 $r_1,r_2$、批内 $N_{\\text{eff}}$ 极差、分段延迟占比、以及被删 token 的注意力分数分位数。前三个用于在线告警，第四个用于离线校准复核。告警阈值不应设成绝对值，而应设成相对源任务基线的偏移量，因为不同任务的压缩率基线本就不同。</p>\n<table class=\"mini\"><thead><tr><th>信号</th><th>指向的失败模式</th><th>首选动作</th></tr></thead><tbody><tr><td>$r_1$ 低于基线、$r_2$ 正常</td><td>第一阶段过度剔除</td><td>下调 $\\tau_1$，回放校准集</td></tr><tr><td>$r_1$ 正常、$r_2$ 偏高</td><td>第二阶段保留过少</td><td>上调 $k$，检查打分同步点</td></tr><tr><td>批内 $N_{\\text{eff}}$ 极差大</td><td>批抖动 / OOM 前兆</td><td>改按 $N_{\\text{eff}}$ 分桶组批</td></tr><tr><td>短请求桶打分延迟占比高</td><td>尾延迟尖刺</td><td>短请求走单阶段捷径</td></tr><tr><td>被删 token 注意力分数偏高</td><td>两阶段标准冲突</td><td>加第一阶段保守下界</td></tr></tbody></table>\n<p>回滚策略要分层。第一层是阈值回滚：把 $\\tau_1$、$k$ 恢复到上一版校准表，无需重启，只影响新请求。第二层是管线回滚：关闭第二阶段细筛，退化为单阶段，代价是压缩率下降但延迟可预测。第三层是版本回滚：当精度回退无法通过阈值解释时，说明训练与推理的管线一致性被破坏——这正是该算法用\"训练与推理共享同一双阶段管线\"来规避的风险，一旦出现，只能回退到上一版权重与管线组合。三层回滚的触发条件必须写进运维手册，且每层都要有对应的精度冒烟测试，否则回滚本身会成为新的不确定性来源。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-43\">四十三 · 双阈值失配与浅层打分的失效边界</h3>\n<p>DUET-VLM 的精度回退几乎从不来自单一阈值的绝对取值，而来自 <span class=\"inline-math\">τ₁</span> 与 <span class=\"inline-math\">τ₂</span> 的<em>相对校准</em>。第一阶段按空间邻域相似度剔除，判据是 <span class=\"inline-math\">max<sub>i∈N(j)</sub> sim(v<sub>j</sub>,v<sub>i</sub>) &lt; τ₁</span>；第二阶段在 LLM 浅层用跨模态注意力分数取 TopK。两者标准不一致时，会出现“第一阶段已删、第二阶段却本应保留”的 token：细节 patch 与邻域高度相似而被粗筛丢弃，但它恰恰是文本指代的对象，浅层注意力本会把它选进 <span class=\"inline-math\">S₂</span>。此时后续层维护的 KV 上下文先天不足，模型表现为“看得见轮廓、答不出属性”，且错误不抛异常、不崩服务，只能从答案质量上察觉，定位成本极高。工程上的判据是监控两阶段保留集合的交集比例：若 <span class=\"inline-math\">|S₂| / |S₁|</span> 在跨任务流量上明显偏离校准集基线，说明阈值已漂移，应先回滚 <span class=\"inline-math\">τ₁</span> 而非调 <span class=\"inline-math\">τ₂</span>。</p>\n<p>第二个失效条件是短请求上的开销倒挂。第二阶段在 LLM 浅层插入打分逻辑，多出一次前向与调度开销；当视觉 token 数少、文本很短时，被压缩掉的 KV 计算量本就有限，而这次额外前向是固定成本，压缩收益被直接抵消，端到端延迟反而上升。可用的粗略判据是：设保留率为 <span class=\"inline-math\">ρ = N<sub>eff</sub>/N<sub>v</sub></span>，只有当后续层的 KV 计算节省 <span class=\"inline-math\">(1−ρ)·L<sub>rest</sub></span> 超过打分层的固定开销 <span class=\"inline-math\">c<sub>score</sub></span> 时才净赚，短序列正是 <span class=\"inline-math\">L<sub>rest</sub></span> 小、<span class=\"inline-math\">c<sub>score</sub></span> 占比高的区间。因此调度层应按序列长度设旁路：低于阈值长度的请求直接走单阶段或跳过第二阶段，避免为省显存而牺牲尾延迟。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>最可能根因</th><th>处置</th></tr></thead><tbody><tr><td>精度回退、答案缺细节</td><td>τ₁ 偏松，跨任务未重校准</td><td>回滚 τ₁，比对 S₁∩S₂ 比例</td></tr><tr><td>短请求延迟升高</td><td>浅层打分开销未被压缩收益覆盖</td><td>按长度旁路第二阶段</td></tr><tr><td>KV 不足、上下文断裂</td><td>两阶段判据不一致误删关键 token</td><td>冻结 τ₂，放宽 τ₁ 复测</td></tr></tbody></table>\n<p>批抖动与路由不均则来自压缩率的请求间方差：同一批内不同图像的有效 token 数 <span class=\"inline-math\">N<sub>eff</sub></span> 差异大，连续批处理按 token 计费时，长保留请求拖住整个 batch，形成尾延迟尖刺；若按请求均分算力，短请求又浪费。监控应采集每请求的 <span class=\"inline-math\">ρ</span> 分布而非均值，方差突增即为抖动前兆。回滚策略上，阈值与打分逻辑应作为可热切换的配置项而非编译进图：一旦精度或延迟指标越界，先切回单阶段管线保吞吐，再离线重校准双阈值，避免在线上做参数搜索。</p>\n<h3 id=\"alg-duet-vlm-two-stage-sec-44\">四十四 · 对照维度：压缩发生在哪一段数据流上</h3>\n<p>把 DUET-VLM 放进同族算法的坐标系，第一刀不该切在“压缩率谁高”，而应切在“压缩点落在数据流的哪一段”。ViTCoP 的筛选发生在预填之前、以文本为查询做一次相关性打分与 token 合并；熵引导视觉剪枝把判据换成视觉侧的信息熵，仍在编码器出口附近一次完成；逐层视觉 token 压缩把剔除动作摊到 LLM 每一层，随层深逐步收缩；多模态全静态量化与量化感知视觉剪枝根本不减 token 数量，而是改数值表示；ApET 走的是近似误差引导，用重建误差决定保留谁。DUET-VLM 的独特之处是压缩点有两个且判据异质：第一阶段用 patch 间空间相似度 $\\mathrm{sim}(\\mathbf{v}_j,\\mathbf{v}_i)$ 做无文本参与的粗筛，第二阶段用浅层跨模态注意力 $a_j$ 做任务相关细筛。这意味着它与“单点压缩”家族不是替代关系，而是把两种判据串联，代价是串联本身引入一次额外前向与调度。</p>\n<p>工程上判断同族算法怎么选，先问一句：你的瓶颈是视觉编码器的算力，还是 LLM 侧的 KV 显存与解码带宽？编码器侧算力受限而 LLM 侧宽裕，单点预语言剪枝（ViTCoP 一类）足够；LLM 侧 KV 吃紧而编码器不是瓶颈，逐层压缩或 DUET-VLM 的第二阶段才是对症的。DUET-VLM 之所以值得在两者都紧的场景里被选中，是因为第一阶段已经把冗余 patch 挡在 LLM 门外，第二阶段的打分只需在收缩后的集合 $\\mathcal{S}_1$ 上做 TopK，打分本身的开销随 $\\lvert\\mathcal{S}_1\\rvert$ 下降。反过来，若第一阶段阈值过松、$\\lvert\\mathcal{S}_1\\rvert$ 接近原始 token 数，第二阶段就退化成一次全量浅层前向，收益被开销吃掉——这正是短序列请求上的典型失效路径。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-45\">四十五 · 判据异质性的代价：阈值耦合与校准负担</h3>\n<p>同族算法里，单判据方法的调参面通常是一个阈值或一个保留比例；DUET-VLM 是两个阈值 $\\tau_1$、$\\tau_2$ 加一个 TopK 的 $k$，且三者耦合。第一阶段剔除过猛，第二阶段再准也无力回天——关键 token 已在 $\\mathcal{S}_1$ 之外被删，KV 上下文不足，精度回退且难以定位是哪一级删错的。这就是失败模式里“两阶段标准不一致导致关键 token 在两阶段间被误删”的机制根源。可用一个耦合约束刻画这种风险：设第一阶段保留率为 $\\rho_1=\\lvert\\mathcal{S}_1\\rvert/N_v$，第二阶段保留率为 $\\rho_2=k/\\lvert\\mathcal{S}_1\\rvert$，总保留率 $\\rho=\\rho_1\\rho_2$，则有效 token 数</p>\n<div class=\"formula\">$$N_{\\text{eff}}=\\sum_i \\text{keep}_i,\\quad \\text{keep}_i=\\mathbb{1}\\left[\\text{sim}(v_i,\\mathcal{N}(v_i))&lt;\\tau_1\\right]\\cdot\\mathbb{1}\\left[a_i^{(l)}&gt;\\tau_2\\right]$$</div>\n<p>两个指示函数的乘积结构说明：任一阶段判负即永久淘汰，误差不可逆。单阶段方法只有一个不可逆点，DUET-VLM 有两个，因此跨任务部署时的校准负担是乘法级的——换任务要同时重扫 $\\tau_1$ 与 $\\tau_2$，而不是只调一个旋钮。对照之下，ApET 的误差引导判据自带任务无关的重建语义，跨任务迁移的校准成本更低；熵引导剪枝的判据是视觉内在统计量，也不依赖文本分布。DUET-VLM 的第二阶段判据依赖浅层跨模态注意力，而注意力分布随任务提示词形态漂移，这是它校准负担偏高的结构性原因，不是实现瑕疵。</p>\n<p>代价要落到系统量上：第二阶段在 LLM 浅层插入打分逻辑，等于在预填路径上多一次前向与一次调度决策。对长视觉序列请求，这次前向的相对开销被后续层的 KV 节省摊薄；对短请求，KV 节省的绝对量小，而固定开销不变，净收益可能为负。所以选型时不能只看平均压缩率，要看请求的视觉 token 长度分布——分布重心偏短时，单阶段方案或纯量化方案更稳。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-46\">四十六 · 与“不减 token”家族的边界：压缩与量化的正交性</h3>\n<p>多模态全静态量化与量化感知视觉剪枝属于另一条轴：它们不动 token 计数 $N_{\\text{eff}}$，只动每个 token 的位宽与数值精度。这条轴与 DUET-VLM 正交，可以叠加，但叠加顺序影响收益归因。先做 token 缩减再量化，量化作用于更少的激活元素，显存与带宽收益相乘；先量化再缩减，缩减判据要在低精度表示上计算相似度与注意力分数，$\\tau_1$ 的判别分辨率下降，相似 patch 更易被误判为不相似而漏删，或反之。工程判断是：把 DUET-VLM 的两阶段筛选放在高精度（BF16/FP16）路径上算判据，把量化施加在保留下来的 token 的后续层计算与 KV 存储上，判据精度与存储收益各得其所。</p>\n<p>量化感知视觉剪枝则试图把两件事缝在一起，用低精度带来的误差信号反过来指导剪枝，其判据与 DUET-VLM 的相似度判据语义不同：前者问“这个 token 在量化后损失多少信息”，后者问“这个 token 与邻居有多冗余”。两者在冗余度极高的图像区域会给出相反结论——一个量化误差大但高度冗余的 patch，量化感知剪枝倾向保留，DUET-VLM 倾向剔除。选型时若你的精度瓶颈来自数值而非上下文长度，量化感知路线优先；若瓶颈是 KV 容量与解码带宽，DUET-VLM 的 token 缩减优先。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-47\">四十七 · 与逐层压缩的时序差异：一次性判决 vs 渐进收缩</h3>\n<p>逐层视觉 token 压缩把剔除分散到多层，每层删一点，序列长度随层深单调下降，KV 也是逐层增长而非一次性分配。DUET-VLM 是“两次判决”：第一阶段在 LLM 之外，第二阶段在浅层一次 TopK 定终局，之后所有层只对 $\\mathcal{S}_2$ 计算并维护 KV。时序差异带来两个系统后果。其一，显存分配的确定性：DUET-VLM 在第二阶段结束后就能确定 KV 的最终尺寸，便于预分配与批调度做容量规划；逐层压缩的 KV 尺寸随层变化，连续批处理下的显存碎片与预留策略更复杂。其二，早退与并行的友好度：一次性判决后，后续层是规整的稠密计算，便于 2-SM MMA 与 tcgen05 路径上的张量核心调度；逐层压缩每层都有变长收缩，内核启动与掩码开销摊在每一层上。</p>\n<p>但渐进收缩在“判据随层演化”上更强：深层注意力比浅层更能反映语义重要性，逐层方法可以在更深层用更可信的分数做更激进的剔除。DUET-VLM 把判决压在浅层，是用“早收缩、早省 KV”换“判据成熟度”。若你的任务对细粒度视觉 grounding 敏感（需要保留小目标、文字区域），浅层注意力分数尚不成熟，误删风险高于逐层方案；此时要么放宽 $\\tau_2$ 提高 $k$，要么改用逐层路线。这是一个明确的适用条件分界，不是精度与吞吐的笼统权衡。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-48\">四十八 · 决策表：按瓶颈、序列形态与任务漂移选型</h3>\n<table class=\"mini\"><thead><tr><th>场景特征</th><th>首选</th><th>次选</th><th>不选的理由</th></tr></thead><tbody>\n<tr><td>编码器算力紧、LLM 侧宽裕</td><td>预语言视觉剪枝（ViTCoP 类）</td><td>熵引导剪枝</td><td>DUET-VLM 第二阶段开销无处摊薄</td></tr>\n<tr><td>KV 显存与解码带宽是主瓶颈</td><td>DUET-VLM 双阶段</td><td>逐层压缩</td><td>纯量化不减 token 数，KV 不降</td></tr>\n<tr><td>视觉 token 序列普遍偏短</td><td>单阶段剪枝或量化</td><td>DUET-VLM 放宽 $\\tau_1$</td><td>打分前向开销抵消压缩收益</td></tr>\n<tr><td>多任务混部、提示词形态漂移</td><td>ApET 误差引导</td><td>逐层压缩</td><td>双阈值需逐任务重校准，运维成本高</td></tr>\n<tr><td>细粒度 grounding、小目标密集</td><td>逐层压缩（深层判据）</td><td>DUET-VLM 提高 $k$</td><td>浅层注意力分数不成熟，误删关键 token</td></tr>\n<tr><td>精度瓶颈来自数值而非上下文</td><td>量化感知视觉剪枝</td><td>全静态量化</td><td>token 缩减不解决数值误差</td></tr>\n<tr><td>需确定性 KV 预分配、规整稠密后续层</td><td>DUET-VLM 双阶段</td><td>单阶段剪枝</td><td>逐层压缩的变长收缩增加调度复杂度</td></tr>\n</tbody></table>\n<p>表的读法是先定瓶颈轴，再看序列形态与任务漂移两条修正轴。瓶颈轴决定“减 token 还是减位宽还是减编码器算力”；序列形态修正“固定开销能否被摊薄”；任务漂移修正“校准成本是否可承受”。三轴都指向 DUET-VLM 时，它才是正确选择，而不是默认选择。特别地，表中“多任务混部”一行把 DUET-VLM 排除在首选之外，理由不是压缩率不够，而是两个阈值的联合重校准在混部场景下会变成持续的运维负担——每来一个新任务域就要重扫二维阈值网格，且第一阶段误删的精度回退难以归因到具体阶段。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-49\">四十九 · 组合与迁移：把 DUET-VLM 当管线的一段而非全部</h3>\n<p>实务上很少纯用某一种。一个可行的组合是把 DUET-VLM 的第一阶段当作前置过滤器，与逐层压缩串联：第一阶段用相似度粗筛把明显冗余的 patch 挡掉，后续层再用逐层判据做渐进收缩，第二阶段则退化为可选的加速档。这样做的代价是判据链更长，但收益是第一阶段的无文本判据不随任务漂移，可作为稳定的底座，把校准负担集中到逐层判据的一个旋钮上。另一种组合是把 DUET-VLM 与量化正交叠加，判据走高精度、存储走低精度，前文已述。</p>\n<p>迁移判断落在一个具体机制上：$\\text{keep}_i$ 的乘积结构决定了两个阈值不可独立优化。跨任务迁移时，先固定 $\\tau_1$ 扫 $\\tau_2$ 与 $k$，观察 $N_{\\text{eff}}$ 与精度的响应曲线；若精度对 $\\tau_1$ 的敏感度显著高于对 $\\tau_2$，说明该任务的关键信息集中在被第一阶段剔除的冗余 patch 里，此时应放宽 $\\tau_1$ 并把压缩压力交给第二阶段——这是把不可逆的两个淘汰点重新分配风险的唯一手段。反之若精度对 $\\tau_2$ 更敏感，说明浅层注意力在该任务上判别力不足，应考虑换用逐层方案而非继续调参。这个诊断动作本身就是选型决策的一部分：调参响应曲线的形状，比任何离线压缩率数字都更能告诉你该留在 DUET-VLM 还是换族。</p>\n\n<h3 id=\"alg-duet-vlm-two-stage-sec-50\">五十 · 同族选型：双阶段何时优于单阶段与纯相关性筛选</h3>\n<p>把 DUET-VLM 放进同族坐标系，差异只在“筛几次、在哪儿筛”。ViTCoP 一类方法在预填前做一次文本相关性筛选与合并，压缩点单一、实现路径短；DUET-VLM 则把筛选拆成编码器后的空间相似度粗筛与 LLM 浅层的跨模态显著性细筛，即 <span class=\"formula\">$$\\mathcal{S}_1 = \\{j \\mid \\max_{i\\in\\mathcal{N}(j)} \\mathrm{sim}(\\mathbf{v}_j,\\mathbf{v}_i) &lt; \\tau_1\\},\\quad \\mathcal{S}_2 = \\mathrm{TopK}(\\{a_j\\}, k),\\ j\\in\\mathcal{S}_1$$</span> 两阶段串联的收益来自互补：粗筛不依赖文本、成本低，细筛带入任务相关性，因此压缩率能高于任一单阶段方案；代价是第二阶段必须在 LLM 浅层插入打分逻辑，多出一次前向与调度开销。选型的核心判断不是“谁压缩率高”，而是“这份开销能否被后续层省下的 KV 计算与显存带宽覆盖”。</p>\n<p>决策表按请求形态与部署约束给出适用条件：</p>\n<table class=\"mini\"><thead><tr><th>场景特征</th><th>优先选择</th><th>理由与代价</th></tr></thead><tbody><tr><td>长视觉序列、多图或高分辨率、解码占比高</td><td>DUET-VLM 双阶段</td><td>粗筛先砍冗余，细筛保留任务关键 token，后续层仅对保留 token 计算并维护 KV，KV 显存与带宽随 <span class=\"formula\">$$N_{\\text{eff}}=\\sum_i \\text{keep}_i$$</span> 线性下降</td></tr><tr><td>短请求、单图低分辨率、预填占比小</td><td>单阶段或纯相关性筛选</td><td>浅层打分开销在短序列上占比高，压缩收益被额外前向抵消</td></tr><tr><td>任务分布稳定、可离线校准阈值</td><td>DUET-VLM</td><td>两阈值一次调好即可复用，训练与推理共享同一管线，无策略错配回退</td></tr><tr><td>跨任务频繁切换、无校准预算</td><td>ViTCoP 式单次筛选</td><td>单阈值敏感度低，避免第一阶段误删细节 token 且难以定位</td></tr></tbody></table>\n<p>失效条件集中在三处。其一，阈值未按任务重新校准：跨任务部署时第一阶段按相似度剔除过多细节 token，精度回退且难以定位是哪一级筛错。其二，两阶段判据不一致——相似度剔除与注意力 TopK 标准错位时，关键 token 在两阶段间被误删，后续层 KV 上下文不足，表现为长答案生成中途失据。其三，短请求上打分逻辑的固定开销压过压缩收益，吞吐不升反降。工程上应把 <span class=\"formula\">$$\\tau_1,\\ \\tau_2,\\ k$$</span> 与批大小、SLO 一起纳入容量规划：先按任务离线扫阈值，再在目标批大小下测“压缩后 KV 字节数 / 每请求浅层打分耗时”这一比值，比值不显著则退回单阶段。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2026 · 跨模态对齐与蒸馏压缩</td></tr><tr><td>解决什么</td><td>单一阶段的视觉 token 压缩要么在编码器侧丢失细节，要么在 LLM 侧压缩不足，训练与推理使用不同压缩策略导致精度…</td></tr><tr><td>一句话机制</td><td>在视觉编码器后做粗粒度冗余剔除，再在 LLM 浅层用注意力显著性做细粒度二次压缩，训练与推理共享同一双阶段管线。</td></tr><tr><td>代价与失效</td><td>第二阶段需在 LLM 浅层插入打分逻辑，增加一次前向与调度开销；两个阈值需按任务调参，跨任务泛化需重新校准</td></tr><tr><td>后继</td><td></td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-duet-vlm-two-stage · 共 8 个片段</p>\n";break;}}})();
